-- MailBlaster AI: all migrations in order (generated by scripts/combine-migrations.mjs - do not edit)
-- Paste into Supabase -> SQL Editor -> New query -> Run. Safe to run once on an empty project.

-- ===== 0001_schema.sql =====
-- MailBlaster AI :: 0001 schema
-- Supabase PostgreSQL is the permanent source of truth. No SQLite, no Redis.
-- All primary keys are UUIDs; all tables are owned by auth.users via user_id.

------------------------------------------------------------------------------
-- helpers
------------------------------------------------------------------------------
create or replace function public.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

------------------------------------------------------------------------------
-- profiles & settings
------------------------------------------------------------------------------
create table public.profiles (
  id          uuid primary key references auth.users(id) on delete cascade,
  email       text,
  full_name   text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table public.user_settings (
  user_id                 uuid primary key references auth.users(id) on delete cascade,
  timezone                text    not null default 'UTC',
  daily_limit             int     not null default 30  check (daily_limit between 1 and 2000),
  min_interval_seconds    int     not null default 600 check (min_interval_seconds >= 0),
  max_interval_seconds    int     not null default 1200 check (max_interval_seconds >= 0),
  business_hours          jsonb   not null default '{"enabled": false, "start": "09:00", "end": "17:00"}',
  weekdays                int[]   not null default '{1,2,3,4,5,6,7}',
  track_opens             boolean not null default true,
  track_clicks            boolean not null default true,
  tracking_disclosure     text    not null default 'This email contains a tracking pixel and tracked links so the sender can see whether it was opened.',
  unsubscribe_footer      boolean not null default true,
  unsubscribe_text        text    not null default 'Don''t want to hear from me? Unsubscribe',
  signature_html          text    not null default '',
  default_followups       jsonb   not null default '[
    {"enabled": true, "delay_days": 3, "condition": "no_reply", "subject": "", "body_html": "<p>Hi {{FirstName|there}},</p><p>Just floating this to the top of your inbox in case it got buried.</p>"},
    {"enabled": true, "delay_days": 4, "condition": "no_reply", "subject": "", "body_html": "<p>Hi {{FirstName|there}},</p><p>Checking in once more - is this something you would like to explore?</p>"},
    {"enabled": true, "delay_days": 7, "condition": "no_reply", "subject": "", "body_html": "<p>Hi {{FirstName|there}},</p><p>I will close the loop on my side unless I hear back. Thanks for your time either way.</p>"}
  ]',
  notifications           jsonb   not null default '{"campaign_completed": true, "reply_received": true, "failed_sending": true, "campaign_paused": true}',
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  check (max_interval_seconds >= min_interval_seconds)
);

------------------------------------------------------------------------------
-- Gmail accounts + encrypted tokens
------------------------------------------------------------------------------
create table public.connected_accounts (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  provider         text not null default 'google' check (provider = 'google'),
  email            text not null,
  display_name     text,
  status           text not null default 'active' check (status in ('active','reauth_required','disconnected','error')),
  scopes           text[] not null default '{}',
  daily_cap        int  not null default 500 check (daily_cap between 1 and 2000), -- provider hard limit, never overridden by presets
  max_concurrent   int  not null default 1 check (max_concurrent between 1 and 5),
  next_send_at     timestamptz,           -- per-account pacing gate
  blocked_until    timestamptz,           -- set after provider quota errors
  blocked_reason   text,
  last_error       text,
  last_error_at    timestamptz,
  last_reply_check_at timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (user_id, email)
);
create index connected_accounts_user_idx on public.connected_accounts(user_id);

-- Refresh/access tokens are AES-256-GCM encrypted by the Worker. RLS is enabled with NO policies:
-- only the service role (Worker) can ever read this table.
create table public.oauth_tokens (
  account_id         uuid primary key references public.connected_accounts(id) on delete cascade,
  refresh_token_enc  text not null,
  access_token_enc   text,
  access_expires_at  timestamptz,
  key_version        int not null default 1,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

------------------------------------------------------------------------------
-- contacts
------------------------------------------------------------------------------
create table public.contacts (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null references auth.users(id) on delete cascade,
  email               text not null check (email = lower(email)),
  first_name          text,
  last_name           text,
  company             text,
  website             text,
  position            text,
  custom_fields       jsonb not null default '{}',
  tags                text[] not null default '{}',
  subscription_status text not null default 'subscribed' check (subscription_status in ('subscribed','unsubscribed','cleaned')),
  consent_source      text,
  consent_at          timestamptz,
  consent_notes       text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (user_id, email)
);
create index contacts_user_created_idx on public.contacts(user_id, created_at desc);
create index contacts_tags_idx on public.contacts using gin(tags);

create table public.contact_groups (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users(id) on delete cascade,
  name           text not null,
  description    text,
  is_segment     boolean not null default false,
  segment_filter jsonb not null default '{}',   -- {"tags": [...], "company": "...", "status": "..."}
  created_at     timestamptz not null default now(),
  unique (user_id, name)
);

create table public.contact_group_members (
  group_id   uuid not null references public.contact_groups(id) on delete cascade,
  contact_id uuid not null references public.contacts(id) on delete cascade,
  added_at   timestamptz not null default now(),
  primary key (group_id, contact_id)
);
create index contact_group_members_contact_idx on public.contact_group_members(contact_id);

------------------------------------------------------------------------------
-- templates
------------------------------------------------------------------------------
create table public.email_templates (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,
  name        text not null,
  category    text not null default 'General',
  subject     text not null default '',
  body_html   text not null default '',
  body_text   text,
  is_starter  boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index email_templates_user_idx on public.email_templates(user_id, category);

------------------------------------------------------------------------------
-- campaigns
------------------------------------------------------------------------------
create table public.campaigns (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references auth.users(id) on delete cascade,
  account_id        uuid references public.connected_accounts(id) on delete set null,
  name              text not null,
  status            text not null default 'draft'
                      check (status in ('draft','scheduled','queued','running','paused','completed','cancelled','failed')),
  subject           text not null default '',
  body_html         text not null default '',
  body_text         text,
  template_id       uuid references public.email_templates(id) on delete set null,
  delivery_mode     text not null default 'send' check (delivery_mode in ('send','draft')),
  settings          jsonb not null default '{}',   -- daily_limit, intervals, timezone, business_hours, weekdays, tracking flags ...
  attachments       jsonb not null default '[]',   -- [{name, path, size, type}] stored in Supabase Storage (private bucket)
  follow_ups_enabled boolean not null default true,
  start_at          timestamptz,
  end_at            timestamptz,
  started_at        timestamptz,
  completed_at      timestamptz,
  paused_at         timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index campaigns_user_idx on public.campaigns(user_id, created_at desc);
create index campaigns_status_idx on public.campaigns(status) where status in ('scheduled','queued','running');

create table public.campaign_recipients (
  id               uuid primary key default gen_random_uuid(),
  campaign_id      uuid not null references public.campaigns(id) on delete cascade,
  user_id          uuid not null references auth.users(id) on delete cascade,
  contact_id       uuid references public.contacts(id) on delete set null,
  email            text not null check (email = lower(email)),
  first_name       text,
  last_name        text,
  company          text,
  website          text,
  position         text,
  fields           jsonb not null default '{}',  -- custom merge fields (CustomField1, anything from the CSV)
  token            text not null unique default replace(gen_random_uuid()::text, '-', ''),
  status           text not null default 'pending'
                     check (status in ('pending','queued','sent','drafted','failed','skipped','bounced','unsubscribed')),
  sent_at          timestamptz,
  open_count       int not null default 0,
  opened_at        timestamptz,
  last_opened_at   timestamptz,
  click_count      int not null default 0,
  first_clicked_at timestamptz,
  last_clicked_at  timestamptz,
  replied_at       timestamptz,
  reply_preview    text,
  follow_ups_sent  int not null default 0,
  followups_stopped boolean not null default false,
  stop_reason      text,
  failure_reason   text,
  skip_reason      text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (campaign_id, email)
);
create index campaign_recipients_campaign_status_idx on public.campaign_recipients(campaign_id, status);
create index campaign_recipients_user_email_idx on public.campaign_recipients(user_id, email);

create table public.follow_up_sequences (
  id          uuid primary key default gen_random_uuid(),
  campaign_id uuid not null unique references public.campaigns(id) on delete cascade,
  user_id     uuid not null references auth.users(id) on delete cascade,
  enabled     boolean not null default true,
  created_at  timestamptz not null default now()
);

create table public.follow_up_steps (
  id               uuid primary key default gen_random_uuid(),
  sequence_id      uuid not null references public.follow_up_sequences(id) on delete cascade,
  user_id          uuid not null references auth.users(id) on delete cascade,
  step_number      int not null check (step_number >= 1),
  enabled          boolean not null default true,
  delay_minutes    int not null check (delay_minutes >= 1),   -- relative to the previous email being submitted
  condition        text not null default 'no_reply' check (condition in ('no_reply','no_open','no_click','always')),
  subject          text not null default '',                  -- empty => "Re: <original subject>"
  body_html        text not null default '',
  body_text        text,
  reply_in_thread  boolean not null default true,
  created_at       timestamptz not null default now(),
  unique (sequence_id, step_number)
);

------------------------------------------------------------------------------
-- queue
------------------------------------------------------------------------------
create table public.sending_jobs (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  campaign_id      uuid not null references public.campaigns(id) on delete cascade,
  recipient_id     uuid not null references public.campaign_recipients(id) on delete cascade,
  account_id       uuid references public.connected_accounts(id) on delete set null,
  step_number      int  not null default 0,        -- 0 = initial email, 1.. = follow-up stages
  status           text not null default 'queued'
                     check (status in ('queued','claimed','sending','submitted','failed','skipped','cancelled','ambiguous')),
  run_after        timestamptz not null default now(),
  attempts         int  not null default 0,
  max_attempts     int  not null default 5,
  locked_by        text,
  lease_expires_at timestamptz,
  claimed_at       timestamptz,
  completed_at     timestamptz,
  idempotency_key  text not null unique,           -- recipient_id:step  => a follow-up can never be created twice
  error_class      text,
  last_error       text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (recipient_id, step_number)
);
create index sending_jobs_due_idx on public.sending_jobs(account_id, run_after) where status = 'queued';
create index sending_jobs_campaign_idx on public.sending_jobs(campaign_id, status);
create index sending_jobs_lease_idx on public.sending_jobs(lease_expires_at) where status in ('claimed','sending');
create index sending_jobs_account_day_idx on public.sending_jobs(account_id, claimed_at)
  where status in ('claimed','sending','submitted','ambiguous');

create table public.email_messages (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  campaign_id      uuid not null references public.campaigns(id) on delete cascade,
  recipient_id     uuid not null references public.campaign_recipients(id) on delete cascade,
  job_id           uuid not null unique references public.sending_jobs(id) on delete cascade,
  account_id       uuid references public.connected_accounts(id) on delete set null,
  step_number      int not null default 0,
  kind             text not null default 'sent' check (kind in ('sent','draft')),
  rfc_message_id   text,
  gmail_message_id text,
  gmail_thread_id  text,
  subject          text,
  to_email         text not null,
  sent_at          timestamptz not null default now()
);
create index email_messages_thread_idx on public.email_messages(account_id, gmail_thread_id);
create index email_messages_recipient_idx on public.email_messages(recipient_id, sent_at desc);

------------------------------------------------------------------------------
-- events
------------------------------------------------------------------------------
create table public.tracking_events (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  campaign_id   uuid not null references public.campaigns(id) on delete cascade,
  recipient_id  uuid not null references public.campaign_recipients(id) on delete cascade,
  event_type    text not null check (event_type in ('open','click')),
  url           text,
  user_agent    text,
  counted       boolean not null default true,  -- false for suspected prefetch/scanner hits (kept for transparency)
  created_at    timestamptz not null default now()
);
create index tracking_events_recipient_idx on public.tracking_events(recipient_id, created_at desc);
create index tracking_events_campaign_idx on public.tracking_events(campaign_id, event_type, created_at desc);

create table public.replies (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  campaign_id      uuid not null references public.campaigns(id) on delete cascade,
  recipient_id     uuid not null references public.campaign_recipients(id) on delete cascade,
  gmail_message_id text not null unique,
  gmail_thread_id  text,
  from_email       text,
  snippet          text,
  received_at      timestamptz not null default now(),
  created_at       timestamptz not null default now()
);
create index replies_user_idx on public.replies(user_id, received_at desc);

create table public.bounces (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users(id) on delete cascade,
  campaign_id      uuid not null references public.campaigns(id) on delete cascade,
  recipient_id     uuid not null references public.campaign_recipients(id) on delete cascade,
  bounce_type      text not null check (bounce_type in ('permanent','temporary')),
  reason           text,
  gmail_message_id text unique,
  detected_at      timestamptz not null default now()
);
create index bounces_user_idx on public.bounces(user_id, detected_at desc);

create table public.suppression_entries (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references auth.users(id) on delete cascade,
  email       text not null check (email = lower(email)),
  reason      text not null default 'manual' check (reason in ('unsubscribed','bounced','manual','complaint')),
  source      text,
  note        text,
  created_at  timestamptz not null default now(),
  unique (user_id, email)
);

create table public.unsubscribe_events (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  campaign_id   uuid references public.campaigns(id) on delete set null,
  recipient_id  uuid references public.campaign_recipients(id) on delete set null,
  email         text not null,
  method        text not null default 'link' check (method in ('link','one_click','manual')),
  user_agent    text,
  created_at    timestamptz not null default now()
);

create table public.activity_logs (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references auth.users(id) on delete cascade,
  campaign_id   uuid references public.campaigns(id) on delete cascade,
  recipient_id  uuid references public.campaign_recipients(id) on delete cascade,
  event_type    text not null,
  message       text not null default '',
  details       jsonb not null default '{}',
  created_at    timestamptz not null default now()
);
create index activity_logs_user_idx on public.activity_logs(user_id, created_at desc);
create index activity_logs_campaign_idx on public.activity_logs(campaign_id, created_at desc);

create table public.notifications (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references auth.users(id) on delete cascade,
  type         text not null,
  title        text not null,
  body         text,
  campaign_id  uuid references public.campaigns(id) on delete cascade,
  read_at      timestamptz,
  created_at   timestamptz not null default now()
);
create index notifications_user_idx on public.notifications(user_id, created_at desc);

-- Fixed-window rate limiter used for unauthenticated endpoints (login, unsubscribe).
create table public.rate_limits (
  key           text primary key,
  window_start  timestamptz not null,
  hits          int not null default 0
);

------------------------------------------------------------------------------
-- updated_at triggers
------------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['profiles','user_settings','connected_accounts','oauth_tokens','contacts',
                           'email_templates','campaigns','campaign_recipients','sending_jobs']
  loop
    execute format('create trigger %I_updated_at before update on public.%I for each row execute function public.set_updated_at()', t, t);
  end loop;
end $$;

------------------------------------------------------------------------------
-- new-user bootstrap: profile + settings (+ starter templates, see 0005)
------------------------------------------------------------------------------
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles(id, email, full_name)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'full_name', null))
  on conflict (id) do nothing;
  insert into public.user_settings(user_id) values (new.id) on conflict do nothing;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
for each row execute function public.handle_new_user();


-- ===== 0002_rls.sql =====
-- MailBlaster AI :: 0002 Row Level Security + grants
-- Principle: authenticated users can READ their own rows everywhere and WRITE only user-managed
-- data (contacts, groups, templates, suppression list, settings). Anything that drives the
-- queue (campaigns, recipients, jobs, events) is only written through SECURITY DEFINER functions.
-- oauth_tokens and rate_limits have RLS enabled and no policies => service_role only.

do $$
declare t text;
begin
  foreach t in array array[
    'profiles','user_settings','connected_accounts','oauth_tokens','contacts','contact_groups',
    'contact_group_members','email_templates','campaigns','campaign_recipients','follow_up_sequences',
    'follow_up_steps','sending_jobs','email_messages','tracking_events','replies','bounces',
    'suppression_entries','unsubscribe_events','activity_logs','notifications','rate_limits']
  loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- Start from zero privileges for client roles, then grant explicitly.
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

-- owner-select policies (tables with user_id)
do $$
declare t text;
begin
  foreach t in array array[
    'profiles','user_settings','connected_accounts','contacts','contact_groups','email_templates',
    'campaigns','campaign_recipients','follow_up_sequences','follow_up_steps','sending_jobs',
    'email_messages','tracking_events','replies','bounces','suppression_entries','unsubscribe_events',
    'activity_logs','notifications']
  loop
    if t = 'profiles' then
      execute 'create policy "own rows select" on public.profiles for select to authenticated using (id = (select auth.uid()))';
    else
      execute format('create policy "own rows select" on public.%I for select to authenticated using (user_id = (select auth.uid()))', t);
    end if;
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;

-- user-managed tables: full CRUD on own rows
do $$
declare t text;
begin
  foreach t in array array['contacts','contact_groups','email_templates','suppression_entries']
  loop
    execute format('create policy "own rows insert" on public.%I for insert to authenticated with check (user_id = (select auth.uid()))', t);
    execute format('create policy "own rows update" on public.%I for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()))', t);
    execute format('create policy "own rows delete" on public.%I for delete to authenticated using (user_id = (select auth.uid()))', t);
    execute format('grant insert, update, delete on public.%I to authenticated', t);
  end loop;
end $$;

-- contact_group_members: ownership flows through the parent group AND the contact
create policy "members select" on public.contact_group_members for select to authenticated
  using (exists (select 1 from public.contact_groups g where g.id = group_id and g.user_id = (select auth.uid())));
create policy "members insert" on public.contact_group_members for insert to authenticated
  with check (
    exists (select 1 from public.contact_groups g where g.id = group_id and g.user_id = (select auth.uid()))
    and exists (select 1 from public.contacts c where c.id = contact_id and c.user_id = (select auth.uid())));
create policy "members delete" on public.contact_group_members for delete to authenticated
  using (exists (select 1 from public.contact_groups g where g.id = group_id and g.user_id = (select auth.uid())));
grant select, insert, delete on public.contact_group_members to authenticated;

-- settings / profile: update only
create policy "own settings update" on public.user_settings for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant update on public.user_settings to authenticated;

create policy "own profile update" on public.profiles for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));
grant update (full_name) on public.profiles to authenticated;

-- notifications: mark as read / delete
create policy "own notifications update" on public.notifications for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy "own notifications delete" on public.notifications for delete to authenticated
  using (user_id = (select auth.uid()));
grant update (read_at), delete on public.notifications to authenticated;

-- connected_accounts: users may only tune non-security settings; everything else is Worker-managed
create policy "own accounts update" on public.connected_accounts for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
grant update (max_concurrent) on public.connected_accounts to authenticated;

-- service role (Worker) gets everything; it has BYPASSRLS on Supabase.
grant all on all tables in schema public to service_role;
grant usage on schema public to anon, authenticated, service_role;

-- Guard: contact owner must also own the account/contacts referenced (defence in depth)
create or replace function public.guard_campaign_account() returns trigger
language plpgsql as $$
begin
  if new.account_id is not null and not exists (
    select 1 from public.connected_accounts a where a.id = new.account_id and a.user_id = new.user_id) then
    raise exception 'account does not belong to campaign owner';
  end if;
  return new;
end $$;
create trigger campaigns_guard_account before insert or update of account_id on public.campaigns
for each row execute function public.guard_campaign_account();


-- ===== 0003_queue.sql =====
-- MailBlaster AI :: 0003 persistent queue
-- The queue is the `sending_jobs` table. Every function whose name starts with `wk_` or `_` is
-- internal (service_role only; see 0006). All of them take an explicit `p_now` so behaviour is
-- deterministic and testable; in production the default `now()` is used.

------------------------------------------------------------------------------
-- small helpers
------------------------------------------------------------------------------
create or replace function public.safe_tz(p text) returns text
language plpgsql stable as $$
declare tz text := coalesce(nullif(p, ''), 'UTC');
begin
  perform now() at time zone tz;
  return tz;
exception when others then
  return 'UTC';
end $$;

-- First instant >= p_ts that lies inside the allowed sending window (weekday + business hours).
-- Weekdays use ISO numbering: 1 = Monday ... 7 = Sunday.
create or replace function public.next_window_start(p_ts timestamptz, p_tz text, p_start time, p_end time, p_weekdays int[])
returns timestamptz language plpgsql stable as $$
declare
  tz text := public.safe_tz(p_tz);
  local_ts timestamp := p_ts at time zone tz;
  wd int[] := case when p_weekdays is null or cardinality(p_weekdays) = 0 then array[1,2,3,4,5,6,7] else p_weekdays end;
  d int; day timestamp; ws timestamp; we timestamp;
begin
  for d in 0..14 loop
    day := date_trunc('day', local_ts) + (d || ' days')::interval;
    if extract(isodow from day)::int = any(wd) then
      ws := day + p_start;
      we := day + p_end;
      if d = 0 then
        if local_ts < ws then return ws at time zone tz; end if;
        if local_ts < we then return p_ts; end if;
      else
        return ws at time zone tz;
      end if;
    end if;
  end loop;
  return p_ts;
end $$;

create or replace function public._next_day_start(p_ts timestamptz, p_tz text) returns timestamptz
language sql stable as $$
  select (date_trunc('day', p_ts at time zone public.safe_tz(p_tz)) + interval '1 day') at time zone public.safe_tz(p_tz)
$$;

create or replace function public._log(p_user uuid, p_campaign uuid, p_recipient uuid, p_type text, p_message text, p_details jsonb default '{}')
returns void language sql as $$
  insert into public.activity_logs(user_id, campaign_id, recipient_id, event_type, message, details)
  values (p_user, p_campaign, p_recipient, p_type, p_message, coalesce(p_details, '{}'::jsonb));
$$;

create or replace function public._notify(p_user uuid, p_type text, p_title text, p_body text, p_campaign uuid default null)
returns void language plpgsql as $$
declare enabled boolean;
begin
  select coalesce((notifications ->> p_type)::boolean, true) into enabled from public.user_settings where user_id = p_user;
  if coalesce(enabled, true) then
    insert into public.notifications(user_id, type, title, body, campaign_id) values (p_user, p_type, p_title, p_body, p_campaign);
  end if;
end $$;

-- Terminal skip/cancel of one job (recipient is marked skipped only for the initial email).
create or replace function public._skip_job(p_job uuid, p_reason text, p_now timestamptz, p_status text default 'skipped')
returns void language plpgsql as $$
declare j public.sending_jobs;
begin
  update public.sending_jobs
     set status = p_status, last_error = p_reason, error_class = 'skipped', completed_at = p_now,
         locked_by = null, lease_expires_at = null
   where id = p_job and status in ('queued','claimed','sending')
   returning * into j;
  if not found then return; end if;
  if j.step_number = 0 then
    update public.campaign_recipients
       set status = case when p_reason = 'unsubscribed' then 'unsubscribed' else 'skipped' end,
           skip_reason = p_reason
     where id = j.recipient_id and status in ('pending','queued');
  end if;
  perform public._log(j.user_id, j.campaign_id, j.recipient_id,
    case when j.step_number = 0 then 'job_skipped' else 'followup_cancelled' end,
    format('%s (%s)', case when j.step_number = 0 then 'Email skipped' else 'Follow-up cancelled' end, p_reason),
    jsonb_build_object('job_id', j.id, 'reason', p_reason, 'step', j.step_number));
end $$;

-- Cancel every queued follow-up for a recipient (reply, unsubscribe, bounce, suppression ...)
create or replace function public._cancel_followups(p_recipient uuid, p_reason text, p_now timestamptz default now())
returns int language plpgsql as $$
declare n int;
begin
  update public.campaign_recipients set followups_stopped = true, stop_reason = coalesce(stop_reason, p_reason)
   where id = p_recipient and not followups_stopped;
  with c as (
    update public.sending_jobs set status = 'cancelled', last_error = p_reason, error_class = 'skipped', completed_at = p_now
     where recipient_id = p_recipient and step_number > 0 and status = 'queued'
     returning user_id, campaign_id, recipient_id, id, step_number)
  select count(*) into n from c;
  return n;
end $$;

create or replace function public._maybe_complete_campaign(p_campaign uuid, p_now timestamptz)
returns void language plpgsql as $$
declare c public.campaigns;
begin
  select * into c from public.campaigns where id = p_campaign for update;
  if not found or c.status not in ('queued','running') then return; end if;
  if exists (select 1 from public.sending_jobs
              where campaign_id = p_campaign and step_number = 0 and status in ('queued','claimed','sending')) then
    return;
  end if;
  update public.campaigns set status = 'completed', completed_at = p_now where id = p_campaign;
  perform public._log(c.user_id, c.id, null, 'campaign_completed', format('Campaign "%s" completed', c.name), '{}');
  perform public._notify(c.user_id, 'campaign_completed', 'Campaign completed', format('"%s" has finished sending.', c.name), c.id);
end $$;

------------------------------------------------------------------------------
-- ATOMIC CLAIM
-- Returns a JSON array of fully-hydrated jobs (usually 0..p_limit entries, at most one per account).
-- Concurrency safety: accounts are locked with FOR UPDATE SKIP LOCKED, then candidate jobs likewise.
-- Two overlapping scheduler runs can therefore never claim the same job or send twice for one account.
------------------------------------------------------------------------------
create or replace function public.wk_claim_jobs(
  p_limit int default 10, p_lease_seconds int default 120, p_worker text default 'worker', p_now timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  out jsonb := '[]'::jsonb;
  acc public.connected_accounts;
  j public.sending_jobs;
  c public.campaigns;
  r public.campaign_recipients;
  st public.follow_up_steps;
  sq public.follow_up_sequences;
  us public.user_settings;
  v_tz text; v_en boolean; v_start time; v_end time; v_wd int[];
  v_limit int; v_today int; v_day_start timestamptz; v_win timestamptz;
  v_min int; v_max int; v_interval int; v_inflight int;
  v_deferred uuid[]; v_reason text; v_thread jsonb;
begin
  -- 1. lease recovery -------------------------------------------------------
  -- claimed but never sent: safe to put back (poison jobs that keep dying are failed)
  update public.sending_jobs set status = 'failed', error_class = 'permanent', completed_at = p_now,
         last_error = 'Worker repeatedly lost the lease before sending', locked_by = null, lease_expires_at = null
   where status = 'claimed' and lease_expires_at < p_now and attempts >= max_attempts;
  update public.sending_jobs set status = 'queued', locked_by = null, lease_expires_at = null, run_after = p_now
   where status = 'claimed' and lease_expires_at < p_now;
  -- sending (HTTP call may have reached Gmail): NEVER requeue blindly -> ambiguous, reconcile first
  with amb as (
    update public.sending_jobs set status = 'ambiguous', locked_by = null, lease_expires_at = null, error_class = 'ambiguous',
           last_error = 'Lease expired while the Gmail request was in flight; outcome unknown (will not be retried blindly).'
     where status = 'sending' and lease_expires_at < p_now
     returning id, user_id, campaign_id, recipient_id)
  insert into public.activity_logs(user_id, campaign_id, recipient_id, event_type, message, details)
  select user_id, campaign_id, recipient_id, 'job_ambiguous',
         'Send outcome unknown after lease expiry; reconciliation required before any retry', jsonb_build_object('job_id', id)
    from amb;

  -- 2. scheduled campaigns whose start time has arrived
  update public.campaigns set status = 'queued' where status = 'scheduled' and coalesce(start_at, p_now) <= p_now;

  -- 3. per-account claim ----------------------------------------------------
  for acc in
    select a.* from public.connected_accounts a
     where a.status = 'active'
       and (a.blocked_until is null or a.blocked_until <= p_now)
       and (a.next_send_at is null or a.next_send_at <= p_now)
       and exists (select 1 from public.sending_jobs sj join public.campaigns cc on cc.id = sj.campaign_id
                    where sj.account_id = a.id and sj.status = 'queued' and sj.run_after <= p_now
                      and (cc.status in ('queued','running') or (cc.status = 'completed' and sj.step_number > 0)))
     order by a.next_send_at nulls first
     limit p_limit
     for update of a skip locked
  loop
    select count(*) into v_inflight from public.sending_jobs where account_id = acc.id and status in ('claimed','sending');
    continue when v_inflight >= acc.max_concurrent;

    v_deferred := '{}';
    for j in
      select sj.* from public.sending_jobs sj join public.campaigns cc on cc.id = sj.campaign_id
       where sj.account_id = acc.id and sj.status = 'queued' and sj.run_after <= p_now
         and (cc.status in ('queued','running') or (cc.status = 'completed' and sj.step_number > 0))
       order by sj.run_after, sj.step_number desc, sj.created_at
       limit 25
       for update of sj skip locked
    loop
      continue when j.campaign_id = any(v_deferred);
      select * into c from public.campaigns where id = j.campaign_id;
      select * into r from public.campaign_recipients where id = j.recipient_id;

      -- campaign end date
      if c.end_at is not null and p_now > c.end_at then
        perform public._skip_job(j.id, 'campaign_window_ended', p_now);
        continue;
      end if;

      -- suppression / unsubscribe, checked before EVERY send
      if r.status in ('unsubscribed','bounced')
         or exists (select 1 from public.suppression_entries s where s.user_id = j.user_id and s.email = r.email)
         or exists (select 1 from public.contacts ct where ct.user_id = j.user_id and ct.email = r.email and ct.subscription_status <> 'subscribed') then
        perform public._skip_job(j.id, case when r.status = 'unsubscribed' then 'unsubscribed' else 'suppressed' end, p_now);
        if j.step_number > 0 then perform public._cancel_followups(r.id, 'suppressed', p_now); end if;
        continue;
      end if;

      -- follow-up rules
      st := null; sq := null;
      if j.step_number > 0 then
        select fs.* into st from public.follow_up_steps fs
          join public.follow_up_sequences q on q.id = fs.sequence_id
         where q.campaign_id = j.campaign_id and fs.step_number = j.step_number;
        select * into sq from public.follow_up_sequences where campaign_id = j.campaign_id;
        v_reason := case
          when st.id is null or not st.enabled or not c.follow_ups_enabled or sq.id is null or not sq.enabled then 'followups_disabled'
          when r.followups_stopped then coalesce(r.stop_reason, 'followups_stopped')
          when r.replied_at is not null then 'replied'
          when r.status <> 'sent' then 'recipient_not_active'
          when st.condition = 'no_open' and r.open_count > 0 then 'opened'
          when st.condition = 'no_click' and r.click_count > 0 then 'clicked'
          else null end;
        if v_reason is not null then
          perform public._skip_job(j.id, v_reason, p_now, 'cancelled');
          continue;
        end if;
      end if;

      -- business hours / weekdays (campaign time zone)
      v_tz := public.safe_tz(c.settings ->> 'timezone');
      v_en := coalesce((c.settings -> 'business_hours' ->> 'enabled')::boolean, false);
      v_start := case when v_en then coalesce(nullif(c.settings -> 'business_hours' ->> 'start', ''), '09:00')::time else time '00:00' end;
      v_end   := case when v_en then coalesce(nullif(c.settings -> 'business_hours' ->> 'end', ''), '17:00')::time else time '23:59:59.999' end;
      v_wd := array(select jsonb_array_elements_text(coalesce(c.settings -> 'weekdays', '[]'::jsonb))::int);
      v_win := public.next_window_start(p_now, v_tz, v_start, v_end, v_wd);
      if v_win > p_now then
        update public.sending_jobs set run_after = v_win
         where account_id = acc.id and campaign_id = j.campaign_id and status = 'queued' and run_after <= p_now;
        v_deferred := v_deferred || j.campaign_id;
        continue;
      end if;

      -- daily limit: the campaign limit, hard-capped by the provider limit of the account
      v_day_start := date_trunc('day', p_now at time zone v_tz) at time zone v_tz;
      select count(*) into v_today from public.sending_jobs
       where account_id = acc.id and status in ('claimed','sending','submitted','ambiguous') and claimed_at >= v_day_start;
      v_limit := least(coalesce((c.settings ->> 'daily_limit')::int, 30), acc.daily_cap);
      if v_today >= v_limit then
        v_win := public.next_window_start(public._next_day_start(p_now, v_tz), v_tz, v_start, v_end, v_wd);
        update public.sending_jobs set run_after = v_win
         where account_id = acc.id and campaign_id = j.campaign_id and status = 'queued' and run_after <= p_now;
        v_deferred := v_deferred || j.campaign_id;
        perform public._log(j.user_id, c.id, null, 'daily_limit_reached',
          format('Daily limit of %s reached; resuming at %s', v_limit, v_win), jsonb_build_object('limit', v_limit, 'resume_at', v_win));
        continue;
      end if;

      -- CLAIM
      update public.sending_jobs
         set status = 'claimed', attempts = attempts + 1, locked_by = p_worker, claimed_at = p_now,
             lease_expires_at = p_now + make_interval(secs => p_lease_seconds), error_class = null
       where id = j.id;
      v_min := greatest(coalesce((c.settings ->> 'min_interval_seconds')::int, 600), 0);
      v_max := greatest(v_min, coalesce((c.settings ->> 'max_interval_seconds')::int, 1200));
      v_interval := v_min + floor(random() * (v_max - v_min + 1))::int;
      update public.connected_accounts set next_send_at = p_now + make_interval(secs => v_interval) where id = acc.id;
      if c.status = 'queued' then
        update public.campaigns set status = 'running', started_at = coalesce(started_at, p_now) where id = c.id;
        perform public._log(c.user_id, c.id, null, 'campaign_started', format('Campaign "%s" started sending', c.name), '{}');
      end if;

      select * into us from public.user_settings where user_id = j.user_id;
      v_thread := null;
      if j.step_number > 0 then
        select jsonb_build_object('thread_id', m.gmail_thread_id, 'rfc_message_id', m.rfc_message_id, 'subject', m.subject)
          into v_thread from public.email_messages m
         where m.recipient_id = r.id and m.kind = 'sent' order by m.sent_at desc limit 1;
      end if;

      out := out || jsonb_build_object(
        'job', jsonb_build_object('id', j.id, 'step_number', j.step_number, 'attempts', j.attempts + 1,
                                  'idempotency_key', j.idempotency_key, 'worker', p_worker, 'claimed_at', p_now,
                                  'user_id', j.user_id),
        'account', jsonb_build_object('id', acc.id, 'email', acc.email, 'display_name', acc.display_name, 'scopes', acc.scopes),
        'campaign', jsonb_build_object('id', c.id, 'name', c.name, 'subject', c.subject, 'body_html', c.body_html,
                                       'body_text', c.body_text, 'delivery_mode', c.delivery_mode, 'settings', c.settings,
                                       'attachments', c.attachments),
        'recipient', jsonb_build_object('id', r.id, 'email', r.email, 'first_name', r.first_name, 'last_name', r.last_name,
                                        'company', r.company, 'website', r.website, 'position', r.position,
                                        'fields', r.fields, 'token', r.token),
        'step', case when st.id is null then null else jsonb_build_object('subject', st.subject, 'body_html', st.body_html,
                      'body_text', st.body_text, 'reply_in_thread', st.reply_in_thread) end,
        'thread', v_thread,
        'user_settings', jsonb_build_object('track_opens', us.track_opens, 'track_clicks', us.track_clicks,
                                            'unsubscribe_footer', us.unsubscribe_footer, 'unsubscribe_text', us.unsubscribe_text,
                                            'signature_html', us.signature_html, 'tracking_disclosure', us.tracking_disclosure));
      exit;
    end loop;
  end loop;
  return out;
end $$;

-- Earliest moment at which any queued job could become claimable (lets the Worker pace short delays in one run).
create or replace function public.wk_peek_next_due(p_now timestamptz default now())
returns timestamptz language sql stable security definer set search_path = public as $$
  select min(greatest(sj.run_after, coalesce(a.next_send_at, p_now), coalesce(a.blocked_until, p_now)))
    from public.sending_jobs sj
    join public.connected_accounts a on a.id = sj.account_id and a.status = 'active'
    join public.campaigns c on c.id = sj.campaign_id
   where sj.status = 'queued' and (c.status in ('queued','running') or (c.status = 'completed' and sj.step_number > 0))
$$;

------------------------------------------------------------------------------
-- job lifecycle
------------------------------------------------------------------------------
-- claimed -> sending. Returns false when the job can no longer be sent (lease lost / campaign paused).
create or replace function public.wk_job_mark_sending(p_job uuid, p_worker text, p_lease_seconds int default 120, p_now timestamptz default now())
returns boolean language plpgsql security definer set search_path = public as $$
declare j public.sending_jobs; cs text;
begin
  select * into j from public.sending_jobs where id = p_job for update;
  if not found or j.status <> 'claimed' or j.locked_by is distinct from p_worker then return false; end if;
  select status into cs from public.campaigns where id = j.campaign_id;
  if cs in ('paused','draft','scheduled') then
    update public.sending_jobs set status = 'queued', locked_by = null, lease_expires_at = null, attempts = greatest(attempts - 1, 0) where id = p_job;
    return false;
  elsif cs in ('cancelled','failed') or cs is null then
    perform public._skip_job(p_job, 'campaign_' || coalesce(cs, 'deleted'), p_now, 'cancelled');
    return false;
  end if;
  update public.sending_jobs set status = 'sending', lease_expires_at = p_now + make_interval(secs => p_lease_seconds) where id = p_job;
  return true;
end $$;

-- Gmail confirmed the submission. THIS is the only place a job becomes `submitted`.
create or replace function public.wk_job_complete_sent(
  p_job uuid, p_kind text, p_gmail_message_id text, p_thread_id text, p_rfc_id text, p_subject text, p_to text,
  p_now timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  j public.sending_jobs; c public.campaigns; sq public.follow_up_sequences; nxt public.follow_up_steps;
  v_next jsonb := null;
begin
  select * into j from public.sending_jobs where id = p_job for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if j.status = 'submitted' then return jsonb_build_object('ok', true, 'duplicate', true); end if;
  if j.status not in ('sending','ambiguous','claimed') then
    return jsonb_build_object('ok', false, 'error', 'bad_status:' || j.status);
  end if;
  update public.sending_jobs set status = 'submitted', completed_at = p_now, locked_by = null, lease_expires_at = null,
         error_class = null, last_error = null where id = p_job;

  insert into public.email_messages(user_id, campaign_id, recipient_id, job_id, account_id, step_number, kind,
                                    rfc_message_id, gmail_message_id, gmail_thread_id, subject, to_email, sent_at)
  values (j.user_id, j.campaign_id, j.recipient_id, j.id, j.account_id, j.step_number, case when p_kind = 'draft' then 'draft' else 'sent' end,
          p_rfc_id, p_gmail_message_id, p_thread_id, p_subject, p_to, p_now)
  on conflict (job_id) do nothing;

  select * into c from public.campaigns where id = j.campaign_id;
  if p_kind = 'draft' then
    update public.campaign_recipients set status = 'drafted', sent_at = p_now where id = j.recipient_id;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'draft_created', 'Gmail draft created for ' || p_to,
                        jsonb_build_object('job_id', j.id, 'gmail_message_id', p_gmail_message_id));
  elsif j.step_number = 0 then
    update public.campaign_recipients set status = 'sent', sent_at = p_now where id = j.recipient_id;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'email_submitted', 'Email submitted to Gmail for ' || p_to,
                        jsonb_build_object('job_id', j.id, 'gmail_message_id', p_gmail_message_id, 'thread_id', p_thread_id));
  else
    update public.campaign_recipients set follow_ups_sent = follow_ups_sent + 1 where id = j.recipient_id;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'followup_submitted',
                        format('Follow-up %s submitted to Gmail for %s', j.step_number, p_to),
                        jsonb_build_object('job_id', j.id, 'gmail_message_id', p_gmail_message_id, 'step', j.step_number));
  end if;

  -- schedule the next enabled follow-up stage (unique(recipient_id, step_number) makes this idempotent)
  if p_kind <> 'draft' and c.follow_ups_enabled then
    select * into sq from public.follow_up_sequences where campaign_id = j.campaign_id and enabled;
    if found then
      select * into nxt from public.follow_up_steps where sequence_id = sq.id and enabled and step_number > j.step_number
       order by step_number limit 1;
      if found then
        insert into public.sending_jobs(user_id, campaign_id, recipient_id, account_id, step_number, status, run_after, idempotency_key)
        values (j.user_id, j.campaign_id, j.recipient_id, j.account_id, nxt.step_number, 'queued',
                p_now + make_interval(mins => nxt.delay_minutes), j.recipient_id::text || ':' || nxt.step_number)
        on conflict do nothing;
        v_next := jsonb_build_object('step', nxt.step_number, 'run_after', p_now + make_interval(mins => nxt.delay_minutes));
        perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'followup_scheduled',
                            format('Follow-up %s scheduled for %s', nxt.step_number, p_to),
                            jsonb_build_object('step', nxt.step_number, 'run_after', p_now + make_interval(mins => nxt.delay_minutes)));
      end if;
    end if;
  end if;

  perform public._maybe_complete_campaign(j.campaign_id, p_now);
  return jsonb_build_object('ok', true, 'next_followup', v_next);
end $$;

-- Failure handling. p_class: transient | permanent | invalid_recipient | auth | quota
create or replace function public.wk_job_complete_failed(
  p_job uuid, p_class text, p_message text, p_block_seconds int default 3600, p_now timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare j public.sending_jobs; a public.connected_accounts; v_delay int; v_final boolean := false; c public.campaigns;
begin
  select * into j from public.sending_jobs where id = p_job for update;
  if not found or j.status not in ('claimed','sending') then return jsonb_build_object('ok', false); end if;
  select * into c from public.campaigns where id = j.campaign_id;

  if p_class = 'auth' then
    update public.connected_accounts set status = 'reauth_required', last_error = left(p_message, 500), last_error_at = p_now
     where id = j.account_id returning * into a;
    update public.sending_jobs set status = 'queued', attempts = greatest(attempts - 1, 0), locked_by = null, lease_expires_at = null,
           run_after = p_now, error_class = 'auth', last_error = left(p_message, 500) where id = p_job;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'account_reauth_required',
                        'Gmail authorization expired or revoked for ' || coalesce(a.email, 'account'), jsonb_build_object('job_id', j.id));
    perform public._notify(j.user_id, 'failed_sending', 'Reconnect Gmail',
                           'Gmail authorization for ' || coalesce(a.email, 'your account') || ' needs to be renewed. Sending is on hold.', j.campaign_id);
  elsif p_class = 'quota' then
    update public.connected_accounts set blocked_until = p_now + make_interval(secs => p_block_seconds),
           blocked_reason = left(p_message, 500), last_error = left(p_message, 500), last_error_at = p_now
     where id = j.account_id;
    update public.sending_jobs set status = 'queued', attempts = greatest(attempts - 1, 0), locked_by = null, lease_expires_at = null,
           run_after = p_now + make_interval(secs => p_block_seconds), error_class = 'quota', last_error = left(p_message, 500)
     where id = p_job;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'quota_exceeded',
                        'Gmail quota reached; account paused for ' || p_block_seconds || 's', jsonb_build_object('job_id', j.id));
  elsif p_class = 'transient' and j.attempts < j.max_attempts then
    v_delay := least(21600, 60 * power(2, j.attempts)::int) + floor(random() * 30)::int;
    update public.sending_jobs set status = 'queued', locked_by = null, lease_expires_at = null,
           run_after = p_now + make_interval(secs => v_delay), error_class = 'transient', last_error = left(p_message, 500)
     where id = p_job;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'job_retry_scheduled',
                        format('Temporary failure, retry %s/%s in %ss: %s', j.attempts, j.max_attempts, v_delay, left(p_message, 200)),
                        jsonb_build_object('job_id', j.id, 'attempts', j.attempts));
  else
    v_final := true;
    update public.sending_jobs set status = 'failed', completed_at = p_now, locked_by = null, lease_expires_at = null,
           error_class = case when p_class = 'transient' then 'transient_exhausted' else p_class end, last_error = left(p_message, 500)
     where id = p_job;
    if j.step_number = 0 then
      update public.campaign_recipients set status = 'failed', failure_reason = left(p_message, 500) where id = j.recipient_id;
    end if;
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'job_failed', 'Sending failed: ' || left(p_message, 300),
                        jsonb_build_object('job_id', j.id, 'class', p_class));
    perform public._notify(j.user_id, 'failed_sending', 'Email failed to send', left(p_message, 300), j.campaign_id);
    perform public._maybe_complete_campaign(j.campaign_id, p_now);
  end if;
  return jsonb_build_object('ok', true, 'final', v_final);
end $$;

-- The HTTP request was sent but we never saw a verdict (timeout/connection drop): do not retry blindly.
create or replace function public.wk_job_mark_ambiguous(p_job uuid, p_message text, p_now timestamptz default now())
returns void language plpgsql security definer set search_path = public as $$
declare j public.sending_jobs;
begin
  update public.sending_jobs set status = 'ambiguous', locked_by = null, lease_expires_at = null, error_class = 'ambiguous',
         last_error = left(p_message, 500)
   where id = p_job and status in ('sending','claimed') returning * into j;
  if found then
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'job_ambiguous',
                        'Gmail request outcome unknown; checking Sent mail before any retry', jsonb_build_object('job_id', j.id));
  end if;
end $$;

-- Reconciliation verdict "Gmail has no such message": safe to queue again.
create or replace function public.wk_job_requeue_ambiguous(p_job uuid, p_now timestamptz default now())
returns boolean language plpgsql security definer set search_path = public as $$
declare j public.sending_jobs;
begin
  update public.sending_jobs set status = 'queued', run_after = p_now, last_error = 'Reconciled: message not found in Gmail, re-queued',
         error_class = null where id = p_job and status = 'ambiguous' returning * into j;
  if found then
    perform public._log(j.user_id, j.campaign_id, j.recipient_id, 'job_requeued', 'Reconciled with Gmail: not sent, re-queued',
                        jsonb_build_object('job_id', j.id));
  end if;
  return found;
end $$;

create or replace function public.wk_list_ambiguous(p_limit int default 10)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'job_id', j.id, 'account_id', j.account_id, 'to', r.email, 'claimed_at', j.claimed_at,
      'scopes', a.scopes, 'subject', c.subject, 'step_number', j.step_number)), '[]'::jsonb)
  from (select * from public.sending_jobs where status = 'ambiguous' order by updated_at limit p_limit) j
  join public.campaign_recipients r on r.id = j.recipient_id
  join public.campaigns c on c.id = j.campaign_id
  join public.connected_accounts a on a.id = j.account_id
$$;

-- User-facing resolution for ambiguous jobs when the account has no read scope to reconcile automatically.
create or replace function public.resolve_job(p_job uuid, p_outcome text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare j public.sending_jobs; r public.campaign_recipients;
begin
  select * into j from public.sending_jobs where id = p_job and user_id = auth.uid() for update;
  if not found then raise exception 'job not found'; end if;
  if j.status <> 'ambiguous' then raise exception 'job is not ambiguous'; end if;
  select * into r from public.campaign_recipients where id = j.recipient_id;
  if p_outcome = 'sent' then
    return public.wk_job_complete_sent(p_job, 'sent', null, null, null, null, r.email, now());
  elsif p_outcome = 'retry' then
    return jsonb_build_object('ok', public.wk_job_requeue_ambiguous(p_job, now()));
  end if;
  raise exception 'outcome must be sent or retry';
end $$;


-- ===== 0004_events.sql =====
-- MailBlaster AI :: 0004 tracking, unsubscribe, replies, bounces, accounts, rate limits
-- Everything here is service_role only (wk_ prefix), called by public Worker endpoints or the cron.

create or replace function public._valid_email(p text) returns boolean
language sql immutable as $$
  select p is not null and length(p) <= 254
     and p ~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'
$$;

-- Cancel everything still queued for this address across all of the user's campaigns.
create or replace function public._cancel_all_for_email(p_user uuid, p_email text, p_reason text, p_now timestamptz)
returns void language plpgsql as $$
begin
  update public.sending_jobs set status = 'cancelled', last_error = p_reason, error_class = 'skipped', completed_at = p_now
   where status = 'queued'
     and recipient_id in (select id from public.campaign_recipients where user_id = p_user and email = p_email);
  update public.campaign_recipients
     set followups_stopped = true,
         stop_reason = coalesce(stop_reason, p_reason),
         skip_reason = case when status in ('pending','queued') then p_reason else skip_reason end,
         status = case when status in ('pending','queued')
                       then (case when p_reason = 'unsubscribed' then 'unsubscribed' else 'skipped' end) else status end
   where user_id = p_user and email = p_email;
end $$;

------------------------------------------------------------------------------
-- open / click tracking
-- Hits within a few seconds of submission are almost always security scanners or prefetchers:
-- they are stored (transparency) but flagged counted=false and not added to open/click counts.
------------------------------------------------------------------------------
create or replace function public.wk_track_open(p_token text, p_ua text default null, p_now timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare r public.campaign_recipients; v_counted boolean;
begin
  select * into r from public.campaign_recipients where token = p_token;
  if not found then return jsonb_build_object('ok', false); end if;
  v_counted := r.sent_at is not null and p_now - r.sent_at >= interval '8 seconds';
  insert into public.tracking_events(user_id, campaign_id, recipient_id, event_type, user_agent, counted, created_at)
  values (r.user_id, r.campaign_id, r.id, 'open', left(p_ua, 300), v_counted, p_now);
  if v_counted then
    update public.campaign_recipients
       set open_count = open_count + 1, opened_at = coalesce(opened_at, p_now), last_opened_at = p_now
     where id = r.id;
    if r.opened_at is null then
      perform public._log(r.user_id, r.campaign_id, r.id, 'email_opened', r.email || ' opened the email', '{}');
    end if;
  end if;
  return jsonb_build_object('ok', true, 'counted', v_counted);
end $$;

create or replace function public.wk_track_click(p_token text, p_url text, p_ua text default null, p_now timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare r public.campaign_recipients; v_counted boolean;
begin
  select * into r from public.campaign_recipients where token = p_token;
  if not found then return jsonb_build_object('ok', false); end if;
  v_counted := r.sent_at is not null and p_now - r.sent_at >= interval '5 seconds';
  insert into public.tracking_events(user_id, campaign_id, recipient_id, event_type, url, user_agent, counted, created_at)
  values (r.user_id, r.campaign_id, r.id, 'click', left(p_url, 2000), left(p_ua, 300), v_counted, p_now);
  if v_counted then
    update public.campaign_recipients
       set click_count = click_count + 1, first_clicked_at = coalesce(first_clicked_at, p_now), last_clicked_at = p_now
     where id = r.id;
    perform public._log(r.user_id, r.campaign_id, r.id, 'link_clicked', r.email || ' clicked a link',
                        jsonb_build_object('url', left(p_url, 500)));
  end if;
  return jsonb_build_object('ok', true, 'counted', v_counted);
end $$;

------------------------------------------------------------------------------
-- unsubscribe (idempotent)
------------------------------------------------------------------------------
create or replace function public.wk_record_unsubscribe(p_token text, p_method text default 'link', p_ua text default null, p_now timestamptz default now())
returns jsonb language plpgsql security definer set search_path = public as $$
declare r public.campaign_recipients; v_new boolean;
begin
  select * into r from public.campaign_recipients where token = p_token;
  if not found then return jsonb_build_object('ok', false); end if;

  insert into public.suppression_entries(user_id, email, reason, source)
  values (r.user_id, r.email, 'unsubscribed', 'unsubscribe link') on conflict (user_id, email) do nothing;
  get diagnostics v_new = row_count;

  update public.contacts set subscription_status = 'unsubscribed'
   where user_id = r.user_id and email = r.email and subscription_status = 'subscribed';

  perform public._cancel_all_for_email(r.user_id, r.email, 'unsubscribed', p_now);
  update public.campaign_recipients set status = 'unsubscribed' where id = r.id;

  if v_new then
    insert into public.unsubscribe_events(user_id, campaign_id, recipient_id, email, method, user_agent, created_at)
    values (r.user_id, r.campaign_id, r.id, r.email, case when p_method = 'one_click' then 'one_click' else 'link' end, left(p_ua, 300), p_now);
    perform public._log(r.user_id, r.campaign_id, r.id, 'unsubscribed', r.email || ' unsubscribed', jsonb_build_object('method', p_method));
  end if;
  return jsonb_build_object('ok', true, 'email', r.email, 'already', not v_new);
end $$;

-- Minimal public lookup for the unsubscribe confirmation page (never returns more than the address)
create or replace function public.wk_unsubscribe_info(p_token text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((select jsonb_build_object('email', r.email, 'unsubscribed', r.status = 'unsubscribed'
                          or exists (select 1 from public.suppression_entries s where s.user_id = r.user_id and s.email = r.email))
                     from public.campaign_recipients r where r.token = p_token), jsonb_build_object('email', null))
$$;

------------------------------------------------------------------------------
-- replies & bounces (matched by Gmail thread id of the message we submitted)
------------------------------------------------------------------------------
create or replace function public.wk_record_reply(
  p_account uuid, p_thread text, p_msg text, p_from text, p_snippet text, p_received timestamptz, p_now timestamptz default now())
returns text language plpgsql security definer set search_path = public as $$
declare m public.email_messages; r public.campaign_recipients; a public.connected_accounts; v_id uuid;
begin
  select * into a from public.connected_accounts where id = p_account;
  if not found then return 'no_account'; end if;
  if lower(coalesce(p_from, '')) = lower(a.email) then return 'self'; end if;
  select * into m from public.email_messages
   where account_id = p_account and gmail_thread_id = p_thread and kind = 'sent' order by sent_at desc limit 1;
  if not found then return 'unmatched'; end if;
  select * into r from public.campaign_recipients where id = m.recipient_id;
  -- Replies from someone other than the recipient (assistant, forwarded) still count as a human reply.
  insert into public.replies(user_id, campaign_id, recipient_id, gmail_message_id, gmail_thread_id, from_email, snippet, received_at)
  values (r.user_id, r.campaign_id, r.id, p_msg, p_thread, lower(p_from), left(p_snippet, 500), coalesce(p_received, p_now))
  on conflict (gmail_message_id) do nothing returning id into v_id;
  if v_id is null then return 'duplicate'; end if;

  update public.campaign_recipients
     set replied_at = coalesce(replied_at, coalesce(p_received, p_now)), reply_preview = left(p_snippet, 300)
   where id = r.id;
  perform public._cancel_followups(r.id, 'reply', p_now);
  perform public._log(r.user_id, r.campaign_id, r.id, 'reply_received', r.email || ' replied', jsonb_build_object('snippet', left(p_snippet, 200)));
  perform public._notify(r.user_id, 'reply_received', 'New reply from ' || r.email, left(p_snippet, 200), r.campaign_id);
  return 'recorded';
end $$;

create or replace function public.wk_record_bounce(
  p_account uuid, p_thread text, p_msg text, p_type text, p_reason text, p_now timestamptz default now())
returns text language plpgsql security definer set search_path = public as $$
declare m public.email_messages; r public.campaign_recipients; v_id uuid;
begin
  select * into m from public.email_messages
   where account_id = p_account and gmail_thread_id = p_thread and kind = 'sent' order by sent_at desc limit 1;
  if not found then return 'unmatched'; end if;
  select * into r from public.campaign_recipients where id = m.recipient_id;
  insert into public.bounces(user_id, campaign_id, recipient_id, bounce_type, reason, gmail_message_id, detected_at)
  values (r.user_id, r.campaign_id, r.id, p_type, left(p_reason, 500), p_msg, p_now)
  on conflict (gmail_message_id) do nothing returning id into v_id;
  if v_id is null then return 'duplicate'; end if;

  if p_type = 'permanent' then
    perform public._cancel_all_for_email(r.user_id, r.email, 'bounced', p_now);
    update public.campaign_recipients set status = 'bounced', failure_reason = left(p_reason, 500) where id = r.id;
    insert into public.suppression_entries(user_id, email, reason, source)
    values (r.user_id, r.email, 'bounced', 'permanent bounce') on conflict (user_id, email) do nothing;
    perform public._log(r.user_id, r.campaign_id, r.id, 'bounce_detected', r.email || ' permanently bounced',
                        jsonb_build_object('reason', left(p_reason, 300)));
    perform public._notify(r.user_id, 'failed_sending', 'Email bounced', r.email || ': ' || left(p_reason, 200), r.campaign_id);
  else
    perform public._log(r.user_id, r.campaign_id, r.id, 'bounce_temporary', 'Temporary delivery problem for ' || r.email,
                        jsonb_build_object('reason', left(p_reason, 300)));
  end if;
  return 'recorded';
end $$;

------------------------------------------------------------------------------
-- accounts & tokens (ciphertext only ever comes from the Worker)
------------------------------------------------------------------------------
create or replace function public.wk_upsert_account(
  p_user uuid, p_email text, p_name text, p_scopes text[], p_refresh_enc text, p_access_enc text, p_access_expires timestamptz,
  p_now timestamptz default now())
returns uuid language plpgsql security definer set search_path = public as $$
declare v_id uuid;
begin
  insert into public.connected_accounts(user_id, email, display_name, status, scopes)
  values (p_user, lower(p_email), p_name, 'active', coalesce(p_scopes, '{}'))
  on conflict (user_id, email) do update
    set status = 'active', scopes = coalesce(p_scopes, '{}'), display_name = coalesce(excluded.display_name, public.connected_accounts.display_name),
        last_error = null, blocked_until = null, blocked_reason = null
  returning id into v_id;

  insert into public.oauth_tokens(account_id, refresh_token_enc, access_token_enc, access_expires_at)
  values (v_id, coalesce(p_refresh_enc, ''), p_access_enc, p_access_expires)
  on conflict (account_id) do update
    set refresh_token_enc = case when excluded.refresh_token_enc = '' then public.oauth_tokens.refresh_token_enc else excluded.refresh_token_enc end,
        access_token_enc = excluded.access_token_enc, access_expires_at = excluded.access_expires_at;

  -- jobs held back by a reauthorization pause resume automatically
  perform public._log(p_user, null, null, 'audit.account_connected', 'Gmail account connected: ' || lower(p_email),
                      jsonb_build_object('scopes', p_scopes));
  return v_id;
end $$;

create or replace function public.wk_store_access_token(p_account uuid, p_access_enc text, p_expires timestamptz)
returns void language sql security definer set search_path = public as $$
  update public.oauth_tokens set access_token_enc = p_access_enc, access_expires_at = p_expires where account_id = p_account;
$$;

create or replace function public.wk_disconnect_account(p_account uuid, p_now timestamptz default now())
returns void language plpgsql security definer set search_path = public as $$
declare a public.connected_accounts;
begin
  select * into a from public.connected_accounts where id = p_account;
  if not found then return; end if;
  delete from public.oauth_tokens where account_id = p_account;
  update public.connected_accounts set status = 'disconnected', scopes = '{}' where id = p_account;
  update public.campaigns set status = 'paused', paused_at = p_now
   where account_id = p_account and status in ('scheduled','queued','running');
  perform public._log(a.user_id, null, null, 'audit.account_disconnected', 'Gmail account disconnected: ' || a.email, '{}');
end $$;

create or replace function public.wk_accounts_for_reply_check(p_min_age_seconds int default 240, p_limit int default 3, p_now timestamptz default now())
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'email', a.email, 'user_id', a.user_id,
           'last_check', a.last_reply_check_at, 'scopes', a.scopes)), '[]'::jsonb)
    from (select * from public.connected_accounts a
           where a.status = 'active' and 'https://www.googleapis.com/auth/gmail.readonly' = any(a.scopes)
             and (a.last_reply_check_at is null or a.last_reply_check_at < p_now - make_interval(secs => p_min_age_seconds))
             and exists (select 1 from public.email_messages m where m.account_id = a.id and m.kind = 'sent'
                          and m.sent_at > p_now - interval '45 days')
           order by a.last_reply_check_at nulls first limit p_limit) a
$$;

create or replace function public.wk_set_reply_checked(p_account uuid, p_at timestamptz)
returns void language sql security definer set search_path = public as $$
  update public.connected_accounts set last_reply_check_at = p_at where id = p_account;
$$;

create or replace function public.wk_thread_ids_for_account(p_account uuid, p_limit int default 500)
returns text[] language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(distinct m.gmail_thread_id), '{}')
    from (select gmail_thread_id from public.email_messages
           where account_id = p_account and kind = 'sent' and gmail_thread_id is not null
             and sent_at > now() - interval '45 days' order by sent_at desc limit p_limit) m
$$;

------------------------------------------------------------------------------
-- rate limiting + housekeeping
------------------------------------------------------------------------------
create or replace function public.wk_rate_limit(p_key text, p_window_seconds int, p_max int, p_now timestamptz default now())
returns boolean language plpgsql security definer set search_path = public as $$
declare v int;
begin
  insert into public.rate_limits as rl(key, window_start, hits) values (p_key, p_now, 1)
  on conflict (key) do update
     set window_start = case when rl.window_start < p_now - make_interval(secs => p_window_seconds) then p_now else rl.window_start end,
         hits = case when rl.window_start < p_now - make_interval(secs => p_window_seconds) then 1 else rl.hits + 1 end
  returning hits into v;
  return v <= p_max;
end $$;

create or replace function public.wk_cleanup(p_now timestamptz default now())
returns void language plpgsql security definer set search_path = public as $$
begin
  delete from public.rate_limits where window_start < p_now - interval '1 day';
  delete from public.notifications where created_at < p_now - interval '90 days';
  delete from public.activity_logs where created_at < p_now - interval '180 days';
end $$;


-- ===== 0004_worker_reads.sql =====
-- MailBlaster AI :: 0004b token / account reads for the Worker (service role only; see 0006).
-- Ciphertext is only ever decrypted inside the Worker; the key is a Cloudflare secret, never in the DB.

create or replace function public.wk_get_tokens(p_account uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
      'account_id', a.id, 'email', a.email, 'user_id', a.user_id, 'status', a.status, 'scopes', a.scopes,
      'refresh_token_enc', t.refresh_token_enc, 'access_token_enc', t.access_token_enc, 'access_expires_at', t.access_expires_at)
    from public.connected_accounts a left join public.oauth_tokens t on t.account_id = a.id where a.id = p_account
$$;

create or replace function public.wk_get_account(p_account uuid, p_user uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select to_jsonb(a) from public.connected_accounts a where a.id = p_account and a.user_id = p_user
$$;

create or replace function public.wk_mark_account_error(p_account uuid, p_status text, p_message text, p_now timestamptz default now())
returns void language sql security definer set search_path = public as $$
  update public.connected_accounts set status = p_status, last_error = left(p_message, 500), last_error_at = p_now where id = p_account;
$$;


-- ===== 0005_campaign_api.sql =====
-- MailBlaster AI :: 0005 user-facing campaign API (called by the Worker with the USER's JWT)
-- Mutations are SECURITY DEFINER with explicit auth.uid() ownership checks because authenticated
-- users have no direct write access to campaigns / recipients / jobs. Reads are SECURITY INVOKER (RLS).

create or replace function public._uid() returns uuid language plpgsql stable as $$
declare u uuid := auth.uid();
begin
  if u is null then raise exception 'not authenticated' using errcode = '28000'; end if;
  return u;
end $$;

create or replace function public._is_suppressed(p_user uuid, p_email text) returns boolean
language sql stable as $$
  select exists (select 1 from public.suppression_entries s where s.user_id = p_user and s.email = p_email)
      or exists (select 1 from public.contacts c where c.user_id = p_user and c.email = p_email and c.subscription_status <> 'subscribed')
$$;

-- Which of these addresses would be excluded? (used by the recipient preview in the UI)
create or replace function public.check_suppressed(p_emails text[]) returns text[]
language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(e), '{}') from (select lower(btrim(x)) e from unnest(p_emails) x) t
   where public._is_suppressed(public._uid(), e)
$$;

------------------------------------------------------------------------------
-- save_campaign: create (p_id null) or update a DRAFT; replaces recipients / follow-up steps when supplied
------------------------------------------------------------------------------
create or replace function public.save_campaign(p_id uuid, p jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := public._uid();
  c public.campaigns;
  us public.user_settings;
  v_settings jsonb; v_defaults jsonb; v_account uuid; v_new boolean := (p_id is null);
  v_inserted int := 0; v_invalid int := 0; v_dups int := 0; v_supp int := 0;
  v_att jsonb; v_att_size bigint; step jsonb; n int := 0; sq_id uuid;
  v_start time; v_end time; v_wd jsonb; v_mode text;
begin
  select * into us from public.user_settings where user_id = uid;

  if v_new then
    if coalesce(btrim(p ->> 'name'), '') = '' then raise exception 'campaign name is required'; end if;
    insert into public.campaigns(user_id, name) values (uid, left(btrim(p ->> 'name'), 200)) returning * into c;
  else
    select * into c from public.campaigns where id = p_id and user_id = uid for update;
    if not found then raise exception 'campaign not found'; end if;
    if c.status <> 'draft' then raise exception 'only draft campaigns can be edited (status: %)', c.status; end if;
  end if;

  v_account := coalesce(nullif(p ->> 'account_id', '')::uuid, c.account_id,
                        (select id from public.connected_accounts where user_id = uid and status = 'active' order by created_at limit 1));
  v_mode := coalesce(p ->> 'delivery_mode', c.delivery_mode);
  if v_mode not in ('send','draft') then raise exception 'delivery_mode must be send or draft'; end if;

  -- settings: user defaults <- stored <- request, then validated
  v_defaults := jsonb_build_object(
      'daily_limit', us.daily_limit, 'min_interval_seconds', us.min_interval_seconds, 'max_interval_seconds', us.max_interval_seconds,
      'timezone', us.timezone, 'business_hours', us.business_hours, 'weekdays', to_jsonb(us.weekdays),
      'track_opens', us.track_opens, 'track_clicks', us.track_clicks, 'unsubscribe_link', us.unsubscribe_footer, 'reply_in_thread', true);
  v_settings := v_defaults || coalesce(c.settings, '{}'::jsonb) || coalesce(p -> 'settings', '{}'::jsonb);
  if (v_settings ->> 'daily_limit')::int not between 1 and 2000 then raise exception 'daily_limit must be between 1 and 2000'; end if;
  if (v_settings ->> 'min_interval_seconds')::int < 0
     or (v_settings ->> 'max_interval_seconds')::int < (v_settings ->> 'min_interval_seconds')::int then
    raise exception 'interval range is invalid (min must be <= max)';
  end if;
  if (v_settings ->> 'max_interval_seconds')::int > 86400 then raise exception 'maximum interval is 24 hours'; end if;
  v_wd := v_settings -> 'weekdays';
  if jsonb_typeof(v_wd) <> 'array' or exists (select 1 from jsonb_array_elements_text(v_wd) w where w::int not between 1 and 7) then
    raise exception 'weekdays must be an array of 1..7 (Monday=1)';
  end if;
  if coalesce((v_settings -> 'business_hours' ->> 'enabled')::boolean, false) then
    v_start := (v_settings -> 'business_hours' ->> 'start')::time;
    v_end := (v_settings -> 'business_hours' ->> 'end')::time;
    if v_start >= v_end then raise exception 'business hours start must be before end'; end if;
  end if;
  v_settings := jsonb_set(v_settings, '{timezone}', to_jsonb(public.safe_tz(v_settings ->> 'timezone')));

  -- attachments: <= 3 files, <= 2 MB total, only inside the caller's own storage prefix
  v_att := coalesce(p -> 'attachments', c.attachments, '[]'::jsonb);
  if jsonb_typeof(v_att) <> 'array' or jsonb_array_length(v_att) > 3 then raise exception 'at most 3 attachments are allowed'; end if;
  select coalesce(sum((a ->> 'size')::bigint), 0) into v_att_size from jsonb_array_elements(v_att) a;
  if v_att_size > 2097152 then raise exception 'attachments exceed 2 MB total'; end if;
  if exists (select 1 from jsonb_array_elements(v_att) a where left(a ->> 'path', length(uid::text) + 1) <> uid::text || '/') then
    raise exception 'attachment path is not owned by the user';
  end if;

  update public.campaigns set
    name = left(coalesce(nullif(btrim(p ->> 'name'), ''), name), 200),
    subject = left(coalesce(p ->> 'subject', subject), 998),
    body_html = left(coalesce(p ->> 'body_html', body_html), 500000),
    body_text = case when p ? 'body_text' then left(p ->> 'body_text', 200000) else body_text end,
    template_id = case when p ? 'template_id' then nullif(p ->> 'template_id', '')::uuid else template_id end,
    delivery_mode = v_mode,
    account_id = v_account,
    settings = v_settings,
    attachments = v_att,
    follow_ups_enabled = coalesce((p #>> '{follow_ups,enabled}')::boolean, follow_ups_enabled),
    start_at = case when p ? 'start_at' then nullif(p ->> 'start_at', '')::timestamptz else start_at end,
    end_at = case when p ? 'end_at' then nullif(p ->> 'end_at', '')::timestamptz else end_at end
  where id = c.id returning * into c;

  if v_new then
    perform public._log(uid, c.id, null, 'campaign_created', format('Campaign "%s" created', c.name), '{}');
  end if;

  -- follow-up sequence
  if p ? 'follow_ups' and jsonb_typeof(p -> 'follow_ups' -> 'steps') = 'array' then
    insert into public.follow_up_sequences(campaign_id, user_id, enabled)
    values (c.id, uid, coalesce((p #>> '{follow_ups,enabled}')::boolean, true))
    on conflict (campaign_id) do update set enabled = excluded.enabled
    returning id into sq_id;
    delete from public.follow_up_steps where sequence_id = sq_id;
    for step in select * from jsonb_array_elements(p -> 'follow_ups' -> 'steps') loop
      n := n + 1;
      if n > 10 then raise exception 'at most 10 follow-up stages are allowed'; end if;
      insert into public.follow_up_steps(sequence_id, user_id, step_number, enabled, delay_minutes, condition, subject, body_html, body_text, reply_in_thread)
      values (sq_id, uid, n, coalesce((step ->> 'enabled')::boolean, true),
              greatest(1, coalesce((step ->> 'delay_minutes')::int, round(coalesce((step ->> 'delay_days')::numeric, 3) * 1440)::int)),
              coalesce(nullif(step ->> 'condition', ''), 'no_reply'),
              left(coalesce(step ->> 'subject', ''), 998), left(coalesce(step ->> 'body_html', ''), 200000), step ->> 'body_text',
              coalesce((step ->> 'reply_in_thread')::boolean, true));
    end loop;
  end if;

  -- recipients: replace the whole list of a draft (one row per person)
  if p ? 'recipients' and jsonb_typeof(p -> 'recipients') = 'array' then
    if jsonb_array_length(p -> 'recipients') > 5000 then raise exception 'at most 5000 recipients per campaign'; end if;
    delete from public.campaign_recipients where campaign_id = c.id;

    select count(*) filter (where not ok), count(*) filter (where ok and rn > 1) into v_invalid, v_dups
      from (select public._valid_email(lower(btrim(t.e ->> 'email'))) as ok,
                   row_number() over (partition by lower(btrim(t.e ->> 'email')) order by t.ord) as rn
              from jsonb_array_elements(p -> 'recipients') with ordinality as t(e, ord)) q;

    with raw as (
      select t.ord, lower(btrim(t.e ->> 'email')) as email, t.e
        from jsonb_array_elements(p -> 'recipients') with ordinality as t(e, ord)),
    checked as (
      select raw.*, public._valid_email(email) as ok,
             row_number() over (partition by email order by ord) as rn
        from raw),
    ins as (
      insert into public.campaign_recipients(campaign_id, user_id, contact_id, email, first_name, last_name, company, website, position, fields, status, skip_reason)
      select c.id, uid,
             (select ct.id from public.contacts ct where ct.user_id = uid and ct.id = nullif(e ->> 'contact_id', '')::uuid),
             email,
             left(nullif(btrim(e ->> 'first_name'), ''), 200), left(nullif(btrim(e ->> 'last_name'), ''), 200),
             left(nullif(btrim(e ->> 'company'), ''), 300), left(nullif(btrim(e ->> 'website'), ''), 300),
             left(nullif(btrim(e ->> 'position'), ''), 300),
             case when jsonb_typeof(e -> 'fields') = 'object' then e -> 'fields' else '{}'::jsonb end,
             case when public._is_suppressed(uid, email) then 'skipped' else 'pending' end,
             case when public._is_suppressed(uid, email) then 'suppressed' end
        from checked where ok and rn = 1 order by ord
      returning status)
    select count(*), count(*) filter (where status = 'skipped') into v_inserted, v_supp from ins;
  end if;

  return jsonb_build_object('id', c.id, 'inserted', v_inserted, 'invalid', v_invalid, 'duplicates', v_dups, 'suppressed', v_supp);
end $$;

------------------------------------------------------------------------------
-- lifecycle
------------------------------------------------------------------------------
create or replace function public.start_campaign(p_id uuid, p_start_at timestamptz default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := public._uid();
  c public.campaigns; a public.connected_accounts;
  v_start timestamptz; v_queued int; v_skipped int; v_status text;
begin
  select * into c from public.campaigns where id = p_id and user_id = uid for update;
  if not found then raise exception 'campaign not found'; end if;
  if c.status <> 'draft' then raise exception 'campaign already started (status: %)', c.status; end if;
  if c.account_id is null then raise exception 'connect a Gmail account first'; end if;
  select * into a from public.connected_accounts where id = c.account_id;
  if a.status <> 'active' then raise exception 'Gmail account % must be reconnected (status: %)', a.email, a.status; end if;
  if c.delivery_mode = 'draft' and not ('https://www.googleapis.com/auth/gmail.compose' = any(a.scopes)) then
    raise exception 'creating Gmail drafts requires the gmail.compose permission; reconnect the account with it enabled';
  end if;
  if btrim(c.subject) = '' then raise exception 'subject is required'; end if;
  if btrim(c.body_html) = '' then raise exception 'message body is required'; end if;

  v_start := greatest(coalesce(p_start_at, c.start_at, now()), now());
  if c.end_at is not null and c.end_at <= v_start then raise exception 'campaign end date must be after the start time'; end if;

  -- exclusions are evaluated again at start (list may have changed since the draft was saved)
  update public.campaign_recipients set status = 'skipped', skip_reason = 'suppressed'
   where campaign_id = c.id and status = 'pending' and public._is_suppressed(uid, email);

  insert into public.sending_jobs(user_id, campaign_id, recipient_id, account_id, step_number, status, run_after, idempotency_key)
  select uid, c.id, r.id, c.account_id, 0, 'queued', v_start, r.id::text || ':0'
    from public.campaign_recipients r where r.campaign_id = c.id and r.status = 'pending'
  on conflict do nothing;
  get diagnostics v_queued = row_count;
  if v_queued = 0 then raise exception 'no eligible recipients (all excluded, invalid, suppressed or the list is empty)'; end if;

  update public.campaign_recipients set status = 'queued' where campaign_id = c.id and status = 'pending';
  select count(*) into v_skipped from public.campaign_recipients where campaign_id = c.id and status = 'skipped';

  v_status := case when v_start > now() + interval '30 seconds' then 'scheduled' else 'queued' end;
  update public.campaigns set status = v_status, start_at = v_start where id = c.id;

  perform public._log(uid, c.id, null, 'jobs_queued', format('%s individual sending jobs queued', v_queued),
                      jsonb_build_object('queued', v_queued, 'skipped', v_skipped));
  if v_status = 'scheduled' then
    perform public._log(uid, c.id, null, 'campaign_scheduled', format('Campaign "%s" scheduled for %s', c.name, v_start),
                        jsonb_build_object('start_at', v_start));
  end if;
  return jsonb_build_object('id', c.id, 'status', v_status, 'queued', v_queued, 'skipped', v_skipped, 'start_at', v_start);
end $$;

create or replace function public.pause_campaign(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid(); c public.campaigns;
begin
  update public.campaigns set status = 'paused', paused_at = now()
   where id = p_id and user_id = uid and status in ('scheduled','queued','running') returning * into c;
  if not found then raise exception 'campaign cannot be paused in its current state'; end if;
  perform public._log(uid, c.id, null, 'campaign_paused', format('Campaign "%s" paused', c.name), '{}');
  perform public._notify(uid, 'campaign_paused', 'Campaign paused', format('"%s" was paused.', c.name), c.id);
  return jsonb_build_object('id', c.id, 'status', 'paused');
end $$;

create or replace function public.resume_campaign(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid(); c public.campaigns; a public.connected_accounts; v_status text;
begin
  select * into c from public.campaigns where id = p_id and user_id = uid for update;
  if not found or c.status <> 'paused' then raise exception 'only paused campaigns can be resumed'; end if;
  select * into a from public.connected_accounts where id = c.account_id;
  if a is null or a.status <> 'active' then raise exception 'the Gmail account must be (re)connected before resuming'; end if;
  v_status := case
    when c.start_at is not null and c.start_at > now() then 'scheduled'
    when exists (select 1 from public.sending_jobs where campaign_id = c.id and status in ('submitted','claimed','sending','ambiguous')) then 'running'
    else 'queued' end;
  update public.campaigns set status = v_status, paused_at = null where id = c.id;
  perform public._log(uid, c.id, null, 'campaign_resumed', format('Campaign "%s" resumed', c.name), '{}');
  return jsonb_build_object('id', c.id, 'status', v_status);
end $$;

create or replace function public.cancel_campaign(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid(); c public.campaigns; n int;
begin
  update public.campaigns set status = 'cancelled' where id = p_id and user_id = uid
     and status in ('scheduled','queued','running','paused','completed') returning * into c;
  if not found then raise exception 'campaign cannot be cancelled in its current state'; end if;
  update public.sending_jobs set status = 'cancelled', last_error = 'campaign_cancelled', error_class = 'skipped', completed_at = now()
   where campaign_id = c.id and status = 'queued';
  get diagnostics n = row_count;
  update public.campaign_recipients set status = 'skipped', skip_reason = 'campaign_cancelled'
   where campaign_id = c.id and status in ('pending','queued');
  update public.campaign_recipients set followups_stopped = true, stop_reason = coalesce(stop_reason, 'campaign_cancelled')
   where campaign_id = c.id;
  perform public._log(uid, c.id, null, 'campaign_cancelled', format('Campaign "%s" cancelled (%s queued jobs cancelled)', c.name, n),
                      jsonb_build_object('cancelled_jobs', n));
  return jsonb_build_object('id', c.id, 'status', 'cancelled', 'cancelled_jobs', n);
end $$;

create or replace function public.delete_campaign(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid();
begin
  delete from public.campaigns where id = p_id and user_id = uid and status = 'draft';
  if not found then raise exception 'only draft campaigns can be deleted'; end if;
end $$;

create or replace function public.duplicate_campaign(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid(); c public.campaigns; nc public.campaigns; sq public.follow_up_sequences; nsq uuid;
begin
  select * into c from public.campaigns where id = p_id and user_id = uid;
  if not found then raise exception 'campaign not found'; end if;
  insert into public.campaigns(user_id, account_id, name, subject, body_html, body_text, template_id, delivery_mode, settings, attachments, follow_ups_enabled)
  values (uid, c.account_id, left(c.name || ' (copy)', 200), c.subject, c.body_html, c.body_text, c.template_id, c.delivery_mode, c.settings, c.attachments, c.follow_ups_enabled)
  returning * into nc;
  select * into sq from public.follow_up_sequences where campaign_id = c.id;
  if found then
    insert into public.follow_up_sequences(campaign_id, user_id, enabled) values (nc.id, uid, sq.enabled) returning id into nsq;
    insert into public.follow_up_steps(sequence_id, user_id, step_number, enabled, delay_minutes, condition, subject, body_html, body_text, reply_in_thread)
    select nsq, uid, step_number, enabled, delay_minutes, condition, subject, body_html, body_text, reply_in_thread
      from public.follow_up_steps where sequence_id = sq.id;
  end if;
  insert into public.campaign_recipients(campaign_id, user_id, contact_id, email, first_name, last_name, company, website, position, fields)
  select nc.id, uid, contact_id, email, first_name, last_name, company, website, position, fields
    from public.campaign_recipients where campaign_id = c.id;
  perform public._log(uid, nc.id, null, 'campaign_created', format('Campaign "%s" created (duplicate of "%s")', nc.name, c.name), '{}');
  return jsonb_build_object('id', nc.id);
end $$;

-- Manual kill switch for follow-ups (also cancels everything still queued).
create or replace function public.set_followups_enabled(p_id uuid, p_enabled boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid(); c public.campaigns; n int := 0;
begin
  update public.campaigns set follow_ups_enabled = p_enabled where id = p_id and user_id = uid returning * into c;
  if not found then raise exception 'campaign not found'; end if;
  if not p_enabled then
    update public.sending_jobs set status = 'cancelled', last_error = 'followups_disabled', error_class = 'skipped', completed_at = now()
     where campaign_id = c.id and step_number > 0 and status = 'queued';
    get diagnostics n = row_count;
    update public.campaign_recipients set followups_stopped = true, stop_reason = coalesce(stop_reason, 'manual')
     where campaign_id = c.id and not followups_stopped;
  end if;
  perform public._log(uid, c.id, null, 'followups_toggled',
                      format('Follow-ups %s for "%s"', case when p_enabled then 'enabled' else 'disabled' end, c.name), jsonb_build_object('cancelled', n));
  return jsonb_build_object('enabled', p_enabled, 'cancelled', n);
end $$;

-- Re-queue jobs that exhausted their retries (transient errors only; permanent failures stay failed).
create or replace function public.retry_failed_jobs(p_id uuid) returns int
language plpgsql security definer set search_path = public as $$
declare uid uuid := public._uid(); n int;
begin
  perform 1 from public.campaigns where id = p_id and user_id = uid;
  if not found then raise exception 'campaign not found'; end if;
  with up as (
    update public.sending_jobs set status = 'queued', attempts = 0, run_after = now(), completed_at = null, last_error = null, error_class = null
     where campaign_id = p_id and user_id = uid and status = 'failed' and error_class = 'transient_exhausted' returning recipient_id, step_number)
  update public.campaign_recipients r set status = 'queued', failure_reason = null
    from up where r.id = up.recipient_id and up.step_number = 0;
  get diagnostics n = row_count;
  update public.campaigns set status = 'queued', completed_at = null where id = p_id and status = 'completed' and n > 0;
  return n;
end $$;

------------------------------------------------------------------------------
-- reads
------------------------------------------------------------------------------
create or replace view public.campaign_stats with (security_invoker = true) as
select r.campaign_id, r.user_id,
       count(*)                                              as total,
       count(*) filter (where r.status = 'pending')           as pending,
       count(*) filter (where r.status = 'queued')            as queued,
       count(*) filter (where r.sent_at is not null)          as sent,
       count(*) filter (where r.status = 'drafted')           as drafted,
       count(*) filter (where r.open_count > 0)               as opened,
       count(*) filter (where r.click_count > 0)              as clicked,
       count(*) filter (where r.replied_at is not null)       as replied,
       count(*) filter (where r.status = 'bounced')           as bounced,
       count(*) filter (where r.status = 'unsubscribed')      as unsubscribed,
       count(*) filter (where r.status = 'failed')            as failed,
       count(*) filter (where r.status = 'skipped')           as skipped,
       coalesce(sum(r.follow_ups_sent), 0)::int               as follow_ups_sent
  from public.campaign_recipients r group by r.campaign_id, r.user_id;
grant select on public.campaign_stats to authenticated;

create or replace function public.list_campaigns(p_status text default null, p_search text default null, p_limit int default 50, p_offset int default 0)
returns jsonb language sql stable security invoker as $$
  with base as (
    select c.id, c.name, c.status, c.subject, c.delivery_mode, c.start_at, c.end_at, c.started_at, c.completed_at, c.created_at,
           c.follow_ups_enabled, c.settings, a.email as account_email,
           coalesce(s.total, 0) total, coalesce(s.pending, 0) pending, coalesce(s.queued, 0) queued, coalesce(s.sent, 0) sent,
           coalesce(s.opened, 0) opened, coalesce(s.clicked, 0) clicked, coalesce(s.replied, 0) replied,
           coalesce(s.bounced, 0) bounced, coalesce(s.unsubscribed, 0) unsubscribed, coalesce(s.failed, 0) failed,
           coalesce(s.skipped, 0) skipped, coalesce(s.follow_ups_sent, 0) follow_ups_sent
      from public.campaigns c
      left join public.campaign_stats s on s.campaign_id = c.id
      left join public.connected_accounts a on a.id = c.account_id
     where c.user_id = auth.uid()
       and (p_status is null or p_status = '' or c.status = p_status)
       and (p_search is null or p_search = '' or c.name ilike concat('%', p_search, '%'))),
  page as (select * from base order by created_at desc limit greatest(p_limit, 1) offset greatest(p_offset, 0))
  select jsonb_build_object('total', (select count(*) from base),
                            'rows', coalesce((select jsonb_agg(to_jsonb(page) order by page.created_at desc) from page), '[]'::jsonb))
$$;

create or replace function public.get_campaign(p_id uuid) returns jsonb
language sql stable security invoker as $$
  select to_jsonb(c)
         || jsonb_build_object(
              'account', (select jsonb_build_object('id', a.id, 'email', a.email, 'status', a.status, 'scopes', a.scopes)
                            from public.connected_accounts a where a.id = c.account_id),
              'stats', coalesce((select to_jsonb(s) - 'user_id' - 'campaign_id' from public.campaign_stats s where s.campaign_id = c.id),
                                '{"total":0,"pending":0,"queued":0,"sent":0,"drafted":0,"opened":0,"clicked":0,"replied":0,"bounced":0,"unsubscribed":0,"failed":0,"skipped":0,"follow_ups_sent":0}'::jsonb),
              'follow_ups', jsonb_build_object(
                  'enabled', coalesce((select q.enabled from public.follow_up_sequences q where q.campaign_id = c.id), true),
                  'steps', coalesce((select jsonb_agg(jsonb_build_object('step_number', fs.step_number, 'enabled', fs.enabled,
                              'delay_minutes', fs.delay_minutes, 'delay_days', round(fs.delay_minutes / 1440.0, 2), 'condition', fs.condition,
                              'subject', fs.subject, 'body_html', fs.body_html, 'body_text', fs.body_text, 'reply_in_thread', fs.reply_in_thread)
                              order by fs.step_number)
                            from public.follow_up_steps fs join public.follow_up_sequences q on q.id = fs.sequence_id
                           where q.campaign_id = c.id), '[]'::jsonb)),
              'jobs', jsonb_build_object(
                  'queued', (select count(*) from public.sending_jobs j where j.campaign_id = c.id and j.status = 'queued' and j.step_number = 0),
                  'followups_queued', (select count(*) from public.sending_jobs j where j.campaign_id = c.id and j.status = 'queued' and j.step_number > 0),
                  'ambiguous', (select count(*) from public.sending_jobs j where j.campaign_id = c.id and j.status = 'ambiguous'),
                  'failed', (select count(*) from public.sending_jobs j where j.campaign_id = c.id and j.status = 'failed'),
                  'next_run_at', (select min(j.run_after) from public.sending_jobs j where j.campaign_id = c.id and j.status = 'queued')))
    from public.campaigns c where c.id = p_id and c.user_id = auth.uid()
$$;

create or replace function public.list_campaign_recipients(
  p_campaign uuid, p_filter text default 'all', p_search text default null, p_sort text default 'created_at',
  p_dir text default 'asc', p_limit int default 50, p_offset int default 0)
returns jsonb language plpgsql stable security invoker as $$
declare v_where text; v_sort text; v_dir text; v_total int; v_rows jsonb;
begin
  v_where := case coalesce(p_filter, 'all')
    when 'all' then 'true'
    when 'pending' then 'r.status = ''pending'''
    when 'queued' then 'r.status = ''queued'''
    when 'sent' then 'r.sent_at is not null'
    when 'opened' then 'r.open_count > 0'
    when 'not_opened' then 'r.sent_at is not null and r.open_count = 0'
    when 'clicked' then 'r.click_count > 0'
    when 'replied' then 'r.replied_at is not null'
    when 'no_reply' then 'r.sent_at is not null and r.replied_at is null'
    when 'bounced' then 'r.status = ''bounced'''
    when 'unsubscribed' then 'r.status = ''unsubscribed'''
    when 'failed' then 'r.status = ''failed'''
    when 'skipped' then 'r.status = ''skipped'''
    else null end;
  if v_where is null then raise exception 'unknown filter %', p_filter; end if;
  v_sort := case when p_sort in ('email','status','sent_at','open_count','click_count','replied_at','created_at','last_opened_at','follow_ups_sent')
                 then p_sort else 'created_at' end;
  v_dir := case when lower(coalesce(p_dir, 'asc')) = 'desc' then 'desc' else 'asc' end;

  execute format($q$select count(*) from public.campaign_recipients r
      where r.campaign_id = $1 and r.user_id = auth.uid() and (%s)
        and ($2 is null or $2 = '' or r.email ilike concat('%%', $2, '%%') or coalesce(r.first_name, '') ilike concat('%%', $2, '%%')
             or coalesce(r.last_name, '') ilike concat('%%', $2, '%%') or coalesce(r.company, '') ilike concat('%%', $2, '%%'))$q$, v_where)
    into v_total using p_campaign, p_search;

  execute format($q$select coalesce(jsonb_agg(to_jsonb(t) order by t.rn), '[]'::jsonb) from (
      select row_number() over (order by r.%I %s nulls last, r.id) as rn,
             r.id, r.email, r.first_name, r.last_name, r.company, r.status, r.sent_at, r.open_count, r.opened_at, r.last_opened_at,
             r.click_count, r.replied_at, r.reply_preview, r.follow_ups_sent, r.failure_reason, r.skip_reason, r.stop_reason, r.followups_stopped,
             (select min(j.run_after) from public.sending_jobs j where j.recipient_id = r.id and j.status = 'queued' and j.step_number > 0) as next_followup_at,
             (select j.id from public.sending_jobs j where j.recipient_id = r.id and j.status = 'ambiguous' limit 1) as ambiguous_job_id
        from public.campaign_recipients r
       where r.campaign_id = $1 and r.user_id = auth.uid() and (%s)
         and ($2 is null or $2 = '' or r.email ilike concat('%%', $2, '%%') or coalesce(r.first_name, '') ilike concat('%%', $2, '%%')
              or coalesce(r.last_name, '') ilike concat('%%', $2, '%%') or coalesce(r.company, '') ilike concat('%%', $2, '%%'))
       order by r.%I %s nulls last, r.id
       limit $3 offset $4) t$q$, v_sort, v_dir, v_where, v_sort, v_dir)
    into v_rows using p_campaign, p_search, greatest(p_limit, 1), greatest(p_offset, 0);
  return jsonb_build_object('total', v_total, 'rows', v_rows);
end $$;

create or replace function public.recipient_detail(p_recipient uuid) returns jsonb
language sql stable security invoker as $$
  select jsonb_build_object(
    'recipient', to_jsonb(r) - 'user_id' - 'token',
    'messages', coalesce((select jsonb_agg(to_jsonb(m) - 'user_id' order by m.sent_at) from public.email_messages m where m.recipient_id = r.id), '[]'),
    'jobs', coalesce((select jsonb_agg(jsonb_build_object('id', j.id, 'step_number', j.step_number, 'status', j.status, 'run_after', j.run_after,
                       'attempts', j.attempts, 'error_class', j.error_class, 'last_error', j.last_error) order by j.step_number)
                       from public.sending_jobs j where j.recipient_id = r.id), '[]'),
    'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at desc)
                          from (select event_type, url, counted, created_at from public.tracking_events where recipient_id = r.id
                                order by created_at desc limit 50) e), '[]'),
    'replies', coalesce((select jsonb_agg(jsonb_build_object('from', x.from_email, 'snippet', x.snippet, 'received_at', x.received_at) order by x.received_at)
                           from public.replies x where x.recipient_id = r.id), '[]'),
    'bounces', coalesce((select jsonb_agg(jsonb_build_object('type', b.bounce_type, 'reason', b.reason, 'detected_at', b.detected_at))
                           from public.bounces b where b.recipient_id = r.id), '[]'),
    'activity', coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc)
                            from (select event_type, message, created_at from public.activity_logs where recipient_id = r.id
                                  order by created_at desc limit 50) a), '[]'))
    from public.campaign_recipients r where r.id = p_recipient and r.user_id = auth.uid()
$$;

------------------------------------------------------------------------------
-- dashboard overview (all numbers computed from tables, nothing hard-coded)
------------------------------------------------------------------------------
create or replace function public.overview_stats() returns jsonb
language plpgsql stable security invoker as $$
declare
  uid uuid := public._uid();
  tz text := public.safe_tz((select timezone from public.user_settings where user_id = uid));
  v jsonb; t record;
begin
  select coalesce(sum(total), 0) total, coalesce(sum(pending + queued), 0) pending, coalesce(sum(sent), 0) sent,
         coalesce(sum(opened), 0) opened, coalesce(sum(clicked), 0) clicked, coalesce(sum(replied), 0) replied,
         coalesce(sum(bounced), 0) bounced, coalesce(sum(failed), 0) failed, coalesce(sum(skipped), 0) skipped,
         coalesce(sum(unsubscribed), 0) unsubscribed
    into t from public.campaign_stats where user_id = uid;
  v := jsonb_build_object(
    'totals', jsonb_build_object(
        'campaigns', (select count(*) from public.campaigns where user_id = uid),
        'recipients', t.total, 'sent', t.sent, 'pending', t.pending, 'opened', t.opened, 'clicked', t.clicked, 'replied', t.replied,
        'bounced', t.bounced, 'failed', t.failed, 'skipped', t.skipped, 'unsubscribed', t.unsubscribed,
        'contacts', (select count(*) from public.contacts where user_id = uid),
        'suppressed', (select count(*) from public.suppression_entries where user_id = uid)),
    'rates', jsonb_build_object(
        'open_rate', case when t.sent > 0 then round(t.opened * 100.0 / t.sent, 1) end,
        'click_rate', case when t.sent > 0 then round(t.clicked * 100.0 / t.sent, 1) end,
        'reply_rate', case when t.sent > 0 then round(t.replied * 100.0 / t.sent, 1) end,
        'bounce_rate', case when t.sent > 0 then round(t.bounced * 100.0 / t.sent, 1) end));

  v := v || jsonb_build_object('daily', (
    select coalesce(jsonb_agg(jsonb_build_object('date', d.day, 'sent', coalesce(s.n, 0), 'opened', coalesce(o.n, 0), 'replied', coalesce(r.n, 0)) order by d.day), '[]')
      from (select ((now() at time zone tz)::date - g) as day from generate_series(0, 29) g) d
      left join (select (sent_at at time zone tz)::date as day, count(*) as n from public.email_messages
                  where user_id = uid and kind = 'sent' and sent_at > now() - interval '31 days' group by 1) s on s.day = d.day
      left join (select (opened_at at time zone tz)::date as day, count(*) as n from public.campaign_recipients
                  where user_id = uid and opened_at > now() - interval '31 days' group by 1) o on o.day = d.day
      left join (select (received_at at time zone tz)::date as day, count(*) as n from public.replies
                  where user_id = uid and received_at > now() - interval '31 days' group by 1) r on r.day = d.day));

  v := v || jsonb_build_object('campaign_performance', (
    select coalesce(jsonb_agg(x order by x.created_at), '[]') from (
      select c.name, c.created_at, coalesce(s.sent, 0) sent, coalesce(s.opened, 0) opened, coalesce(s.replied, 0) replied, coalesce(s.bounced, 0) bounced
        from public.campaigns c left join public.campaign_stats s on s.campaign_id = c.id
       where c.user_id = uid and c.status <> 'draft' order by c.created_at desc limit 8) x));

  v := v || jsonb_build_object('recent_activity', (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc), '[]') from (
      select a.id, a.event_type, a.message, a.created_at, c.name as campaign_name
        from public.activity_logs a left join public.campaigns c on c.id = a.campaign_id
       where a.user_id = uid and a.event_type not like 'audit.%' order by a.created_at desc limit 10) x));

  v := v || jsonb_build_object('recent_replies', (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.received_at desc), '[]') from (
      select rp.id, rp.from_email, rp.snippet, rp.received_at, c.name as campaign_name, c.id as campaign_id
        from public.replies rp join public.campaigns c on c.id = rp.campaign_id
       where rp.user_id = uid order by rp.received_at desc limit 5) x));

  v := v || jsonb_build_object('upcoming', (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.start_at), '[]') from (
      select c.id, c.name, c.status, c.start_at, coalesce(s.total, 0) recipients
        from public.campaigns c left join public.campaign_stats s on s.campaign_id = c.id
       where c.user_id = uid and c.status in ('scheduled','queued') order by c.start_at limit 5) x));

  v := v || jsonb_build_object('failed_jobs', (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc), '[]') from (
      select j.id, j.status, j.error_class, j.last_error, j.updated_at, j.campaign_id, c.name as campaign_name, r.email
        from public.sending_jobs j join public.campaign_recipients r on r.id = j.recipient_id join public.campaigns c on c.id = j.campaign_id
       where j.user_id = uid and j.status in ('failed','ambiguous') order by j.updated_at desc limit 10) x));
  return v;
end $$;

create or replace function public.analytics_overview(p_days int default 30) returns jsonb
language plpgsql stable security invoker as $$
declare
  uid uuid := public._uid();
  tz text := public.safe_tz((select timezone from public.user_settings where user_id = uid));
  n int := least(greatest(coalesce(p_days, 30), 1), 180);
begin
  return jsonb_build_object(
    'days', n,
    'daily', (select coalesce(jsonb_agg(jsonb_build_object('date', d.day, 'sent', coalesce(s.n, 0), 'opened', coalesce(o.n, 0),
                      'clicked', coalesce(k.n, 0), 'replied', coalesce(r.n, 0), 'bounced', coalesce(b.n, 0)) order by d.day), '[]')
        from (select ((now() at time zone tz)::date - g) as day from generate_series(0, n - 1) g) d
        left join (select (sent_at at time zone tz)::date as day, count(*) as n from public.email_messages
                    where user_id = uid and kind = 'sent' and sent_at > now() - make_interval(days => n + 1) group by 1) s on s.day = d.day
        left join (select (created_at at time zone tz)::date as day, count(*) as n from public.tracking_events
                    where user_id = uid and event_type = 'open' and counted and created_at > now() - make_interval(days => n + 1) group by 1) o on o.day = d.day
        left join (select (created_at at time zone tz)::date as day, count(*) as n from public.tracking_events
                    where user_id = uid and event_type = 'click' and counted and created_at > now() - make_interval(days => n + 1) group by 1) k on k.day = d.day
        left join (select (received_at at time zone tz)::date as day, count(*) as n from public.replies
                    where user_id = uid and received_at > now() - make_interval(days => n + 1) group by 1) r on r.day = d.day
        left join (select (detected_at at time zone tz)::date as day, count(*) as n from public.bounces
                    where user_id = uid and bounce_type = 'permanent' and detected_at > now() - make_interval(days => n + 1) group by 1) b on b.day = d.day),
    'top_links', (select coalesce(jsonb_agg(x), '[]') from (
        select url, count(*) clicks, count(distinct recipient_id) unique_clickers from public.tracking_events
         where user_id = uid and event_type = 'click' and counted and created_at > now() - make_interval(days => n)
         group by url order by count(*) desc limit 10) x),
    'by_campaign', (select coalesce(jsonb_agg(x order by x.sent desc), '[]') from (
        select c.id, c.name, coalesce(s.sent, 0) sent, coalesce(s.opened, 0) opened, coalesce(s.clicked, 0) clicked,
               coalesce(s.replied, 0) replied, coalesce(s.bounced, 0) bounced
          from public.campaigns c left join public.campaign_stats s on s.campaign_id = c.id
         where c.user_id = uid and c.status <> 'draft' order by c.created_at desc limit 20) x));
end $$;

------------------------------------------------------------------------------
-- contacts
------------------------------------------------------------------------------
create or replace function public.import_contacts(p_rows jsonb, p_group uuid default null, p_consent_source text default 'import')
returns jsonb language plpgsql security invoker as $$
declare uid uuid := public._uid(); v_ins int; v_upd int; v_invalid int; v_dups int; v_ids uuid[];
begin
  if jsonb_typeof(p_rows) <> 'array' then raise exception 'rows must be an array'; end if;
  if jsonb_array_length(p_rows) > 10000 then raise exception 'at most 10000 contacts per import'; end if;
  if p_group is not null and not exists (select 1 from public.contact_groups where id = p_group and user_id = uid) then
    raise exception 'group not found';
  end if;
  with raw as (
    select t.ord, lower(btrim(t.e ->> 'email')) email, t.e from jsonb_array_elements(p_rows) with ordinality t(e, ord)),
  chk as (select raw.*, public._valid_email(email) ok, row_number() over (partition by email order by ord) rn from raw),
  ups as (
    insert into public.contacts as ct(user_id, email, first_name, last_name, company, website, position, custom_fields, tags, consent_source, consent_at)
    select uid, email, left(nullif(btrim(e ->> 'first_name'), ''), 200), left(nullif(btrim(e ->> 'last_name'), ''), 200),
           left(nullif(btrim(e ->> 'company'), ''), 300), left(nullif(btrim(e ->> 'website'), ''), 300), left(nullif(btrim(e ->> 'position'), ''), 300),
           case when jsonb_typeof(e -> 'fields') = 'object' then e -> 'fields' else '{}'::jsonb end,
           coalesce(array(select jsonb_array_elements_text(case when jsonb_typeof(e -> 'tags') = 'array' then e -> 'tags' else '[]'::jsonb end)), '{}'),
           left(p_consent_source, 200), now()
      from chk where ok and rn = 1
    on conflict (user_id, email) do update set
      first_name = coalesce(excluded.first_name, ct.first_name), last_name = coalesce(excluded.last_name, ct.last_name),
      company = coalesce(excluded.company, ct.company), website = coalesce(excluded.website, ct.website),
      position = coalesce(excluded.position, ct.position), custom_fields = ct.custom_fields || excluded.custom_fields,
      tags = (select coalesce(array_agg(distinct x), '{}') from unnest(ct.tags || excluded.tags) x)
    returning ct.id, (xmax = 0) as inserted),
  agg as (select ups.id, ups.inserted from ups)
  select count(*) filter (where inserted), count(*) filter (where not inserted),
         (select count(*) from chk where not ok), (select count(*) from chk where ok and rn > 1), coalesce(array_agg(id), '{}')
    into v_ins, v_upd, v_invalid, v_dups, v_ids from agg;
  -- separate statement: the RLS check on group membership must be able to see the contacts just written
  if p_group is not null and cardinality(v_ids) > 0 then
    insert into public.contact_group_members(group_id, contact_id) select p_group, x from unnest(v_ids) x on conflict do nothing;
  end if;
  return jsonb_build_object('inserted', v_ins, 'updated', v_upd, 'invalid', v_invalid, 'duplicates', v_dups);
end $$;

create or replace function public.group_contacts(p_group uuid) returns setof public.contacts
language sql stable security invoker as $$
  select c.* from public.contacts c join public.contact_groups g on g.id = p_group and g.user_id = c.user_id
   where c.user_id = auth.uid() and (
     (not g.is_segment and exists (select 1 from public.contact_group_members m where m.group_id = g.id and m.contact_id = c.id))
     or (g.is_segment
         and (coalesce(jsonb_array_length(g.segment_filter -> 'tags'), 0) = 0
              or c.tags && array(select jsonb_array_elements_text(g.segment_filter -> 'tags')))
         and (coalesce(g.segment_filter ->> 'company', '') = '' or c.company ilike concat('%', g.segment_filter ->> 'company', '%'))
         and (coalesce(g.segment_filter ->> 'status', '') = '' or c.subscription_status = g.segment_filter ->> 'status')))
$$;

create or replace function public.export_my_data() returns jsonb
language plpgsql stable security invoker as $$
declare uid uuid := public._uid();
begin
  return jsonb_build_object(
    'exported_at', now(),
    'profile', (select to_jsonb(p) from public.profiles p where p.id = uid),
    'settings', (select to_jsonb(s) from public.user_settings s where s.user_id = uid),
    'connected_accounts', (select coalesce(jsonb_agg(to_jsonb(a)), '[]') from public.connected_accounts a where a.user_id = uid),
    'contacts', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.contacts x where x.user_id = uid),
    'contact_groups', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.contact_groups x where x.user_id = uid),
    'templates', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.email_templates x where x.user_id = uid),
    'campaigns', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.campaigns x where x.user_id = uid),
    'campaign_recipients', (select coalesce(jsonb_agg(to_jsonb(x) - 'token'), '[]') from public.campaign_recipients x where x.user_id = uid),
    'email_messages', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.email_messages x where x.user_id = uid),
    'tracking_events', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.tracking_events x where x.user_id = uid),
    'replies', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.replies x where x.user_id = uid),
    'bounces', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.bounces x where x.user_id = uid),
    'suppression_entries', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.suppression_entries x where x.user_id = uid),
    'unsubscribe_events', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from public.unsubscribe_events x where x.user_id = uid),
    'activity_logs', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from (select * from public.activity_logs where user_id = uid order by created_at desc limit 10000) x));
end $$;

